import * as THREE from "three";
import { getGlowTexture } from "./textures.js";

const PARTICLE_COUNT = 760;
const RING_COUNT = 10;
const FLASH_COUNT = 18;

export class FX {
  constructor(scene, camera, popupContainer) {
    this.scene = scene;
    this.camera = camera;
    this.popupContainer = popupContainer;
    this.trauma = 0;
    this.roll = 0;
    this.shakeOffset = new THREE.Vector3();
    this.time = 0;

    this._tmp = new THREE.Vector3();
    this._tmpColor = new THREE.Color();
    this._proj = new THREE.Vector3();

    this._buildParticles();
    this._buildRings();
    this._buildFlashes();

    this.popups = [];
  }

  _buildParticles() {
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const colors = new Float32Array(PARTICLE_COUNT * 3);
    positions.fill(-999);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    const mat = new THREE.PointsMaterial({
      size: 0.24,
      map: getGlowTexture(),
      vertexColors: true,
      transparent: true,
      opacity: 0.95,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 4;
    this.scene.add(this.points);

    this.pVel = new Float32Array(PARTICLE_COUNT * 3);
    this.pLife = new Float32Array(PARTICLE_COUNT);
    this.pMax = new Float32Array(PARTICLE_COUNT);
    this.pDrag = new Float32Array(PARTICLE_COUNT);
    this.pGrav = new Float32Array(PARTICLE_COUNT);
    this.pBase = new Float32Array(PARTICLE_COUNT * 3);
    this.pCursor = 0;
  }

  _buildRings() {
    this.rings = [];
    const geo = new THREE.RingGeometry(0.72, 0.92, 48, 1);
    for (let i = 0; i < RING_COUNT; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.visible = false;
      mesh.renderOrder = 3;
      this.scene.add(mesh);
      this.rings.push({ mesh, life: 0, max: 0.5, from: 1, to: 6, baseOpacity: 0.8 });
    }
    this.ringCursor = 0;
  }

  _buildFlashes() {
    this.flashes = [];
    for (let i = 0; i < FLASH_COUNT; i++) {
      const mat = new THREE.SpriteMaterial({
        map: getGlowTexture(),
        color: 0xffffff,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        depthTest: true,
      });
      const sprite = new THREE.Sprite(mat);
      sprite.visible = false;
      sprite.renderOrder = 5;
      this.scene.add(sprite);
      this.flashes.push({ sprite, life: 0, max: 0.08, size: 1 });
    }
    this.flashCursor = 0;
  }

  addShake(amount) {
    this.trauma = Math.min(1, this.trauma + amount);
  }

  spawnBurst(pos, color, count = 22, speed = 7, opts = {}) {
    const base = this._tmpColor.set(color);
    const grav = opts.gravity ?? 9;
    for (let n = 0; n < count; n++) {
      const i = this.pCursor;
      this.pCursor = (this.pCursor + 1) % PARTICLE_COUNT;
      const i3 = i * 3;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const v = speed * (0.35 + Math.random() * 0.85);
      const sx = Math.sin(phi) * Math.cos(theta);
      const sy = Math.cos(phi) * 0.8 + (opts.up ?? 0.35);
      const sz = Math.sin(phi) * Math.sin(theta);
      const posAttr = this.points.geometry.attributes.position.array;
      posAttr[i3] = pos.x + (Math.random() - 0.5) * 0.4;
      posAttr[i3 + 1] = pos.y + (Math.random() - 0.5) * 0.4;
      posAttr[i3 + 2] = pos.z + (Math.random() - 0.5) * 0.4;
      this.pVel[i3] = sx * v;
      this.pVel[i3 + 1] = sy * v;
      this.pVel[i3 + 2] = sz * v;
      this.pGrav[i] = grav;
      this.pDrag[i] = opts.drag ?? 2.1;
      const life = (opts.life ?? 0.65) * (0.55 + Math.random() * 0.8);
      this.pLife[i] = life;
      this.pMax[i] = life;
      const tint = 0.72 + Math.random() * 0.28;
      this.pBase[i3] = base.r * tint;
      this.pBase[i3 + 1] = base.g * tint;
      this.pBase[i3 + 2] = base.b * tint;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.color.needsUpdate = true;
  }

  spawnSparks(pos, dir, color, count = 8) {
    const base = this._tmpColor.set(color);
    for (let n = 0; n < count; n++) {
      const i = this.pCursor;
      this.pCursor = (this.pCursor + 1) % PARTICLE_COUNT;
      const i3 = i * 3;
      const posAttr = this.points.geometry.attributes.position.array;
      const spread = 2.4;
      const v = 4 + Math.random() * 5;
      posAttr[i3] = pos.x;
      posAttr[i3 + 1] = pos.y;
      posAttr[i3 + 2] = pos.z;
      this.pVel[i3] = (dir.x + (Math.random() - 0.5) * spread) * v * 0.55;
      this.pVel[i3 + 1] = (0.2 + Math.random() * 0.7) * 3;
      this.pVel[i3 + 2] = (dir.z + (Math.random() - 0.5) * spread) * v * 0.55;
      this.pGrav[i] = 12;
      this.pDrag[i] = 3;
      const life = 0.18 + Math.random() * 0.28;
      this.pLife[i] = life;
      this.pMax[i] = life;
      this.pBase[i3] = base.r;
      this.pBase[i3 + 1] = base.g;
      this.pBase[i3 + 2] = base.b;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.color.needsUpdate = true;
  }

  ring(pos, color, from = 1, to = 6, duration = 0.5, opacity = 0.85, y = 0.12) {
    const r = this.rings[this.ringCursor];
    this.ringCursor = (this.ringCursor + 1) % RING_COUNT;
    r.mesh.position.set(pos.x, y, pos.z);
    r.mesh.material.color.set(color);
    r.mesh.material.opacity = opacity;
    r.mesh.visible = true;
    r.mesh.scale.setScalar(from);
    r.life = duration;
    r.max = duration;
    r.from = from;
    r.to = to;
    r.baseOpacity = opacity;
  }

  flash(pos, color, size = 1.6) {
    const f = this.flashes[this.flashCursor];
    this.flashCursor = (this.flashCursor + 1) % FLASH_COUNT;
    f.sprite.position.copy(pos);
    f.sprite.material.color.set(color);
    f.sprite.material.opacity = 1;
    f.sprite.scale.setScalar(size);
    f.sprite.visible = true;
    f.life = 0.075;
    f.max = 0.075;
    f.size = size;
  }

  impact(pos, color = 0xffd166) {
    this.spawnSparks(pos, { x: 0, z: 0 }, color, 6);
    this.flash(pos, color, 0.9);
  }

  popup(worldPos, text, cls = "") {
    const el = document.createElement("div");
    el.className = `popup ${cls}`;
    el.textContent = text;
    this.popupContainer.appendChild(el);
    this.popups.push({
      el,
      pos: new THREE.Vector3(worldPos.x, worldPos.y, worldPos.z),
      life: 1.05,
      max: 1.05,
    });
  }

  clear() {
    const posAttr = this.points?.geometry.attributes.position;
    if (posAttr) {
      const a = posAttr.array;
      for (let i = 0; i < PARTICLE_COUNT; i++) {
        a[i * 3 + 1] = -999;
        this.pLife[i] = 0;
      }
      posAttr.needsUpdate = true;
    }
    for (const r of this.rings) {
      r.life = 0;
      r.mesh.visible = false;
    }
    for (const f of this.flashes) {
      f.life = 0;
      f.sprite.visible = false;
    }
    for (const p of this.popups) p.el.remove();
    this.popups.length = 0;
    this.trauma = 0;
  }

  update(dt, camera, width, height) {
    this.time += dt;
    this.trauma = Math.max(0, this.trauma - dt * 2.4);
    const amp = this.trauma * this.trauma;
    this.shakeOffset.set(
      (Math.random() - 0.5) * amp * 1.5,
      (Math.random() - 0.5) * amp * 1.1,
      (Math.random() - 0.5) * amp * 1.2
    );
    this.roll = (Math.random() - 0.5) * amp * 0.035;

    // particles
    const posAttr = this.points.geometry.attributes.position.array;
    const colAttr = this.points.geometry.attributes.color.array;
    let anyAlive = false;
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      if (this.pLife[i] <= 0) continue;
      anyAlive = true;
      const i3 = i * 3;
      this.pLife[i] -= dt;
      const life = this.pLife[i];
      if (life <= 0) {
        posAttr[i3 + 1] = -999;
        continue;
      }
      const drag = Math.max(0, 1 - this.pDrag[i] * dt);
      this.pVel[i3] *= drag;
      this.pVel[i3 + 2] *= drag;
      this.pVel[i3 + 1] = this.pVel[i3 + 1] * drag - this.pGrav[i] * dt;
      posAttr[i3] += this.pVel[i3] * dt;
      posAttr[i3 + 1] += this.pVel[i3 + 1] * dt;
      posAttr[i3 + 2] += this.pVel[i3 + 2] * dt;
      if (posAttr[i3 + 1] < 0.08) {
        posAttr[i3 + 1] = 0.08;
        this.pVel[i3 + 1] *= -0.32;
      }
      const fade = Math.pow(Math.max(0, life / this.pMax[i]), 1.35);
      colAttr[i3] = this.pBase[i3] * fade;
      colAttr[i3 + 1] = this.pBase[i3 + 1] * fade;
      colAttr[i3 + 2] = this.pBase[i3 + 2] * fade;
    }
    if (anyAlive || this.points.geometry.attributes.position.needsUpdate) {
      this.points.geometry.attributes.position.needsUpdate = true;
      this.points.geometry.attributes.color.needsUpdate = true;
    }

    // rings
    for (const r of this.rings) {
      if (r.life <= 0) continue;
      r.life -= dt;
      if (r.life <= 0) {
        r.mesh.visible = false;
        continue;
      }
      const k = 1 - r.life / r.max;
      const s = r.from + (r.to - r.from) * (1 - Math.pow(1 - k, 2.4));
      r.mesh.scale.setScalar(s);
      r.mesh.material.opacity = r.baseOpacity * Math.pow(1 - k, 1.4);
    }

    // muzzle flashes
    for (const f of this.flashes) {
      if (f.life <= 0) continue;
      f.life -= dt;
      if (f.life <= 0) {
        f.sprite.visible = false;
        continue;
      }
      const k = 1 - f.life / f.max;
      f.sprite.material.opacity = 1 - k;
      f.sprite.scale.setScalar(f.size * (0.5 + k * 1.7));
    }

    // floating score popups
    for (let i = this.popups.length - 1; i >= 0; i--) {
      const p = this.popups[i];
      p.life -= dt;
      if (p.life <= 0) {
        p.el.remove();
        this.popups.splice(i, 1);
        continue;
      }
      const k = 1 - p.life / p.max;
      this._proj.copy(p.pos);
      this._proj.y += k * 2.1;
      this._proj.project(camera);
      if (this._proj.z > 1) {
        p.el.style.opacity = "0";
        continue;
      }
      const x = (this._proj.x * 0.5 + 0.5) * width;
      const y = (-this._proj.y * 0.5 + 0.5) * height;
      const scale = k < 0.12 ? 0.6 + (k / 0.12) * 0.65 : 1.25 - Math.min(0.25, (k - 0.12) * 0.6);
      p.el.style.left = `${x}px`;
      p.el.style.top = `${y}px`;
      p.el.style.opacity = String(Math.min(1, (1 - k) * 2.2));
      p.el.style.transform = `translate(-50%, -50%) scale(${scale.toFixed(3)})`;
    }
  }
}

import * as THREE from "three";
import { getGlowTexture, makeFloorTexture } from "./textures.js";

export const CELL = 2.2;
export const WALL_H = 2.7;

// 21 x 21 — symmetric, four power pellets, open arena rows at the bottom.
export const LAYOUT = [
  "#####################",
  "#.........#.........#",
  "#.###.###.#.###.###.#",
  "#o###.###.#.###.###o#",
  "#...................#",
  "#.###.#.#####.#.###.#",
  "#.....#...#...#.....#",
  "#####.###.#.###.#####",
  "#.......#...#.......#",
  "#.#####.#.#.#.#####.#",
  "#.#.....#.#.#.....#.#",
  "#.#.###.#.#.#.###.#.#",
  "#...#...........#...#",
  "###.#.###.#.###.#.###",
  "#...#...#...#...#...#",
  "#.###.#.#.#.#.#.###.#",
  "#o....#.......#....o#",
  "#.#####.#####.#####.#",
  "#...................#",
  "#...................#",
  "#####################",
];

const PLAYER_CELL = { x: 10, y: 18 };

export class Maze {
  constructor(scene) {
    this.scene = scene;
    this.rows = LAYOUT;
    this.h = this.rows.length;
    this.w = this.rows[0].length;
    this.size = this.w * CELL;

    this.group = new THREE.Group();
    this.group.name = "maze";
    scene.add(this.group);

    this.walls = [];
    this.wallSet = new Set();
    this.openCells = [];
    this.pelletCells = [];
    this.powerCells = [];

    this._dummy = new THREE.Object3D();
    this._color = new THREE.Color();
    this._cell = { x: 0, y: 0 };
    this._pathPrev = new Int32Array(this.w * this.h);
    this._pathQueue = new Int32Array(this.w * this.h);
    this._pathVisited = new Int32Array(this.w * this.h);

    this.playerSpawn = new THREE.Vector3();
    this.ghostSpawns = [];
    this.level = 1;
    this.collected = 0;

    this._parse();
    this._build();
    this.resetPellets(1);
  }

  _parse() {
    for (let y = 0; y < this.h; y++) {
      const row = this.rows[y];
      for (let x = 0; x < this.w; x++) {
        const ch = row[x];
        if (ch === "#") {
          this.walls.push({ x, y });
          this.wallSet.add(y * this.w + x);
        } else {
          this.openCells.push({ x, y });
          this.pelletCells.push({ x, y, alive: true, instance: -1 });
          if (ch === "o") this.powerCells.push({ x, y, alive: true });
        }
      }
    }

    this.cellToWorld(PLAYER_CELL.x, PLAYER_CELL.y, this.playerSpawn);

    // Find eight open cells ringing the maze center for ghost spawns.
    const center = this.nearestOpenCell(Math.floor(this.w / 2), Math.floor(this.h / 2));
    const candidates = [];
    for (const c of this.openCells) {
      const d = Math.hypot(c.x - center.x, c.y - center.y);
      if (d > 0.5 && d < 7) candidates.push({ ...c, d });
    }
    candidates.sort((a, b) => a.d - b.d);
    const chosen = [];
    for (const c of candidates) {
      if (chosen.length >= 8) break;
      if (chosen.every((o) => Math.hypot(o.x - c.x, o.y - c.y) > 2)) chosen.push(c);
    }
    if (chosen.length === 0) chosen.push(center);
    for (const c of chosen) {
      this.ghostSpawns.push(this.cellToWorld(c.x, c.y, new THREE.Vector3()));
    }
    this.centerCell = center;
    this.centerSpawn = this.cellToWorld(center.x, center.y, new THREE.Vector3());
  }

  _build() {
    const wallCount = this.walls.length;

    // Floor
    const accent = new THREE.Color().setHSL(190 / 360, 1, 0.58);
    this.accent = accent;
    this.borderColor = new THREE.Color(0xff3fbe);
    this.floorTex = makeFloorTexture(accent);
    this.floor = new THREE.Mesh(
      new THREE.PlaneGeometry(this.size + 46, this.size + 46),
      new THREE.MeshBasicMaterial({ map: this.floorTex, color: 0xffffff })
    );
    this.floor.rotation.x = -Math.PI / 2;
    this.floor.position.y = -0.02;
    this.group.add(this.floor);

    // Center glow wash
    this.glowDisc = new THREE.Mesh(
      new THREE.PlaneGeometry(this.size * 1.35, this.size * 1.35),
      new THREE.MeshBasicMaterial({
        map: getGlowTexture(),
        color: accent.clone(),
        transparent: true,
        opacity: 0.12,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      })
    );
    this.glowDisc.rotation.x = -Math.PI / 2;
    this.glowDisc.position.y = 0.015;
    this.glowDisc.renderOrder = 1;
    this.group.add(this.glowDisc);

    // Grid lines aligned with cell boundaries
    const half = this.size / 2;
    const pts = [];
    for (let i = 0; i <= this.w; i++) {
      const x = -half + i * CELL;
      pts.push(x, 0, -half, x, 0, half);
    }
    for (let i = 0; i <= this.h; i++) {
      const z = -half + i * CELL;
      pts.push(-half, 0, z, half, 0, z);
    }
    const gridGeo = new THREE.BufferGeometry();
    gridGeo.setAttribute("position", new THREE.Float32BufferAttribute(pts, 3));
    this.grid = new THREE.LineSegments(
      gridGeo,
      new THREE.LineBasicMaterial({
        color: accent.clone().offsetHSL(0, 0, -0.12),
        transparent: true,
        opacity: 0.2,
        depthWrite: false,
      })
    );
    this.grid.position.y = 0.008;
    this.group.add(this.grid);

    // Walls
    const wallGeo = new THREE.BoxGeometry(CELL * 0.98, WALL_H, CELL * 0.98);
    const wallMat = new THREE.MeshStandardMaterial({
      color: 0x0b1531,
      emissive: 0x061229,
      emissiveIntensity: 0.9,
      roughness: 0.42,
      metalness: 0.62,
    });
    this.wallMesh = new THREE.InstancedMesh(wallGeo, wallMat, wallCount);
    this.wallMesh.instanceMatrix.setUsage(THREE.StaticDrawUsage);
    this.wallMesh.frustumCulled = false;

    const trimGeo = new THREE.BoxGeometry(CELL * 0.96, 0.085, CELL * 0.96);
    this.trimMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    this.trimMesh = new THREE.InstancedMesh(trimGeo, this.trimMat, wallCount);
    this.trimMesh.instanceMatrix.setUsage(THREE.StaticDrawUsage);
    this.trimMesh.frustumCulled = false;
    this.trimMesh.renderOrder = 2;

    const glowGeo = new THREE.PlaneGeometry(CELL * 1.16, CELL * 1.16);
    this.underMat = new THREE.MeshBasicMaterial({
      color: accent.clone(),
      transparent: true,
      opacity: 0.16,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    this.underMesh = new THREE.InstancedMesh(glowGeo, this.underMat, wallCount);
    this.underMesh.build = null;
    this.underMesh.frustumCulled = false;
    this.underMesh.renderOrder = 1;

    this.walls.forEach((cell, i) => {
      this.cellToWorld(cell.x, cell.y, this._dummy.position);
      this._dummy.position.y = WALL_H / 2;
      this._dummy.rotation.set(0, 0, 0);
      this._dummy.scale.set(1, 1, 1);
      this._dummy.updateMatrix();
      this.wallMesh.setMatrixAt(i, this._dummy.matrix);

      this._dummy.position.y = WALL_H + 0.035;
      this._dummy.updateMatrix();
      this.trimMesh.setMatrixAt(i, this._dummy.matrix);

      this._dummy.position.y = 0.035;
      this._dummy.rotation.set(-Math.PI / 2, 0, 0);
      this._dummy.updateMatrix();
      this.underMesh.setMatrixAt(i, this._dummy.matrix);
      this._dummy.rotation.set(0, 0, 0);

      const isBorder =
        cell.x === 0 || cell.y === 0 || cell.x === this.w - 1 || cell.y === this.h - 1;
      this.trimMesh.setColorAt(i, isBorder ? this.borderColor : accent);
      this.underMesh.setColorAt(i, isBorder ? this.borderColor : accent);
    });
    this.wallMesh.instanceMatrix.needsUpdate = true;
    this.trimMesh.instanceMatrix.needsUpdate = true;
    this.underMesh.instanceMatrix.needsUpdate = true;
    this.trimMesh.instanceColor.needsUpdate = true;
    this.underMesh.instanceColor.needsUpdate = true;
    this.group.add(this.wallMesh, this.trimMesh, this.underMesh);

    // Perimeter line outside the border walls
    const edge = half + CELL * 0.56;
    const borderGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(-edge, 0, -edge),
      new THREE.Vector3(edge, 0, -edge),
      new THREE.Vector3(edge, 0, edge),
      new THREE.Vector3(-edge, 0, edge),
      new THREE.Vector3(-edge, 0, -edge),
    ]);
    this.edge = new THREE.Line(
      borderGeo,
      new THREE.LineBasicMaterial({
        color: this.borderColor,
        transparent: true,
        opacity: 0.55,
        depthWrite: false,
      })
    );
    this.edge.position.y = 0.06;
    this.group.add(this.edge);

    // Pellets
    const pelletGeo = new THREE.SphereGeometry(0.155, 8, 6);
    this.pelletMat = new THREE.MeshBasicMaterial({ color: 0xbdf8ff });
    const pelletCount = this.pelletCells.length;
    this.pelletMesh = new THREE.InstancedMesh(pelletGeo, this.pelletMat, pelletCount);
    this.pelletMesh.frustumCulled = false;
    this.pelletMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.group.add(this.pelletMesh);

    this._dummy.position.set(0, 0.58, 0);
    this._dummy.rotation.set(0, 0, 0);
    this._dummy.scale.set(1, 1, 1);
    this._dummy.updateMatrix();
    this._basePelletMatrix = this._dummy.matrix.clone();
    this._zeroMatrix = new THREE.Matrix4().makeScale(0, 0, 0);

    // Power pellets (separate meshes so they can pulse)
    const powerGeo = new THREE.SphereGeometry(0.32, 16, 12);
    this.powerObjs = [];
    for (const p of this.powerCells) {
      const pos = this.cellToWorld(p.x, p.y, new THREE.Vector3());
      const group = new THREE.Group();
      group.position.copy(pos);
      const core = new THREE.Mesh(
        powerGeo,
        new THREE.MeshBasicMaterial({ color: 0xfff0a0 })
      );
      core.position.y = 0.62;
      const halo = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: getGlowTexture(),
          color: 0xffd34d,
          transparent: true,
          opacity: 0.65,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        })
      );
      halo.scale.setScalar(3.1);
      halo.position.y = 0.62;
      group.add(core, halo);
      this.group.add(group);
      this.powerObjs.push({ cell: p, pos, group, core, halo, phase: Math.random() * 6.28 });
      p.obj = this.powerObjs[this.powerObjs.length - 1];
    }

    // Spawn pad
    const pad = new THREE.Mesh(
      new THREE.RingGeometry(1.0, 1.3, 40),
      new THREE.MeshBasicMaterial({
        color: 0xffd400,
        transparent: true,
        opacity: 0.3,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
      })
    );
    pad.rotation.x = -Math.PI / 2;
    pad.position.copy(this.playerSpawn).setY(0.04);
    this.spawnPad = pad;
    this.group.add(pad);

    // Floating dust
    const dustCount = 240;
    const dustPos = new Float32Array(dustCount * 3);
    for (let i = 0; i < dustCount; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = 6 + Math.random() * (this.size * 0.75);
      dustPos[i * 3] = Math.cos(a) * r;
      dustPos[i * 3 + 1] = 1.5 + Math.random() * 16;
      dustPos[i * 3 + 2] = Math.sin(a) * r;
    }
    const dustGeo = new THREE.BufferGeometry();
    dustGeo.setAttribute("position", new THREE.BufferAttribute(dustPos, 3));
    this.dustMat = new THREE.PointsMaterial({
      color: 0x67d9ff,
      size: 0.18,
      map: getGlowTexture(),
      transparent: true,
      opacity: 0.6,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true,
    });
    this.dust = new THREE.Points(dustGeo, this.dustMat);
    this.dust.frustumCulled = false;
    this.group.add(this.dust);
  }

  cellToWorld(x, y, target = new THREE.Vector3()) {
    return target.set(
      (x - (this.w - 1) / 2) * CELL,
      0,
      (y - (this.h - 1) / 2) * CELL
    );
  }

  worldToCell(x, z) {
    this._cell.x = Math.round(x / CELL + (this.w - 1) / 2);
    this._cell.y = Math.round(z / CELL + (this.h - 1) / 2);
    return this._cell;
  }

  isWallCell(x, y) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return true;
    return this.wallSet.has(y * this.w + x);
  }

  isWallAtWorld(x, z) {
    const c = this.worldToCell(x, z);
    return this.isWallCell(c.x, c.y);
  }

  nearestOpenCell(x, y) {
    let best = this.openCells[0];
    let bestD = Infinity;
    for (const c of this.openCells) {
      const d = (c.x - x) * (c.x - x) + (c.y - y) * (c.y - y);
      if (d < bestD) {
        bestD = d;
        best = c;
      }
    }
    return best;
  }

  resolveCircle(pos, radius) {
    for (let pass = 0; pass < 2; pass++) {
      const cx = Math.round(pos.x / CELL + (this.w - 1) / 2);
      const cz = Math.round(pos.z / CELL + (this.h - 1) / 2);
      const half = CELL / 2;
      for (let oy = -1; oy <= 1; oy++) {
        for (let ox = -1; ox <= 1; ox++) {
          const gx = cx + ox;
          const gy = cz + oy;
          if (!this.isWallCell(gx, gy)) continue;
          const bx = (gx - (this.w - 1) / 2) * CELL;
          const bz = (gy - (this.h - 1) / 2) * CELL;
          const nx = Math.max(bx - half, Math.min(pos.x, bx + half));
          const nz = Math.max(bz - half, Math.min(pos.z, bz + half));
          let dx = pos.x - nx;
          let dz = pos.z - nz;
          const d2 = dx * dx + dz * dz;
          if (d2 >= radius * radius) continue;
          if (d2 > 1e-9) {
            const d = Math.sqrt(d2);
            pos.x += (dx / d) * (radius - d);
            pos.z += (dz / d) * (radius - d);
          } else {
            const px = pos.x - bx;
            const pz = pos.z - bz;
            const penX = half + radius - Math.abs(px);
            const penZ = half + radius - Math.abs(pz);
            if (penX < penZ) pos.x += (px < 0 ? -1 : 1) * penX;
            else pos.z += (pz < 0 ? -1 : 1) * penZ;
          }
        }
      }
    }
  }

  hasLineOfSight(a, b) {
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const dist = Math.hypot(dx, dz);
    const steps = Math.max(2, Math.ceil(dist / 0.45));
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      if (this.isWallAtWorld(a.x + dx * t, a.z + dz * t)) return false;
    }
    return true;
  }

  findPath(sx, sy, tx, ty) {
    if (this.isWallCell(sx, sy) || this.isWallCell(tx, ty)) return [];
    const W = this.w;
    const start = sy * W + sx;
    const goal = ty * W + tx;
    if (start === goal) return [];
    const prev = this._pathPrev;
    const visited = this._pathVisited;
    const queue = this._pathQueue;
    visited.fill(0);
    prev.fill(-1);
    let head = 0;
    let tail = 0;
    queue[tail++] = start;
    visited[start] = 1;
    let found = false;
    while (head < tail) {
      const cur = queue[head++];
      if (cur === goal) {
        found = true;
        break;
      }
      const cx = cur % W;
      const cy = (cur - cx) / W;
      if (cx > 0 && !this.isWallCell(cx - 1, cy) && !visited[cur - 1]) {
        visited[cur - 1] = 1;
        prev[cur - 1] = cur;
        queue[tail++] = cur - 1;
      }
      if (cx < W - 1 && !this.isWallCell(cx + 1, cy) && !visited[cur + 1]) {
        visited[cur + 1] = 1;
        prev[cur + 1] = cur;
        queue[tail++] = cur + 1;
      }
      if (cy > 0 && !this.isWallCell(cx, cy - 1) && !visited[cur - W]) {
        visited[cur - W] = 1;
        prev[cur - W] = cur;
        queue[tail++] = cur - W;
      }
      if (cy < this.h - 1 && !this.isWallCell(cx, cy + 1) && !visited[cur + W]) {
        visited[cur + W] = 1;
        prev[cur + W] = cur;
        queue[tail++] = cur + W;
      }
    }
    if (!found) return [];
    const path = [];
    let cur = goal;
    while (cur !== start && cur !== -1) {
      const x = cur % W;
      const y = (cur - x) / W;
      path.push({ x, y });
      cur = prev[cur];
    }
    path.reverse();
    return path;
  }

  collectAt(pos, radius) {
    let pellets = 0;
    let power = 0;
    const r2 = radius * radius;
    for (let i = 0; i < this.pelletCells.length; i++) {
      const p = this.pelletCells[i];
      if (!p.alive) continue;
      const px = (p.x - (this.w - 1) / 2) * CELL;
      const pz = (p.y - (this.h - 1) / 2) * CELL;
      const dx = px - pos.x;
      const dz = pz - pos.z;
      if (dx * dx + dz * dz <= r2) {
        p.alive = false;
        this.collected++;
        this._dummy.position.set(px, 0.58, pz);
        this._dummy.scale.setScalar(0);
        this._dummy.rotation.set(0, 0, 0);
        this._dummy.updateMatrix();
        this.pelletMesh.setMatrixAt(i, this._dummy.matrix);
        this.pelletMesh.instanceMatrix.needsUpdate = true;
        pellets++;
      }
    }
    for (const p of this.powerCells) {
      if (!p.alive) continue;
      const dx = p.obj.pos.x - pos.x;
      const dz = p.obj.pos.z - pos.z;
      if (dx * dx + dz * dz <= r2 + 0.35) {
        p.alive = false;
        p.obj.group.visible = false;
        power++;
      }
    }
    return { pellets, power };
  }

  get pelletsLeft() {
    let n = 0;
    for (const p of this.pelletCells) if (p.alive) n++;
    for (const p of this.powerCells) if (p.alive) n++;
    return n;
  }

  resetPellets(level) {
    this.level = level;
    this.collected = 0;
    for (let i = 0; i < this.pelletCells.length; i++) {
      const p = this.pelletCells[i];
      p.alive = true;
      const px = (p.x - (this.w - 1) / 2) * CELL;
      const pz = (p.y - (this.h - 1) / 2) * CELL;
      this._dummy.position.set(px, 0.58, pz);
      this._dummy.rotation.set(0, 0, 0);
      this._dummy.scale.set(1, 1, 1);
      this._dummy.updateMatrix();
      this.pelletMesh.setMatrixAt(i, this._dummy.matrix);
    }
    this.pelletMesh.instanceMatrix.needsUpdate = true;
    for (const p of this.powerCells) {
      p.alive = true;
      p.obj.group.visible = true;
    }
    this.setLevel(level);
  }

  setLevel(level) {
    const hue = ((190 + (level - 1) * 21) % 360) / 360;
    const accent = this.accent.setHSL(hue, 1, 0.58);
    this.grid.material.color.copy(accent).offsetHSL(0, 0, -0.14);
    this.glowDisc.material.color.copy(accent);
    this.underMat.color.copy(accent);
    this.edge.material.color.copy(this.borderColor);
    this.trimMesh.setColorAt(0, this.borderColor);
    for (let i = 0; i < this.walls.length; i++) {
      const cell = this.walls[i];
      const isBorder =
        cell.x === 0 || cell.y === 0 || cell.x === this.w - 1 || cell.y === this.h - 1;
      this.trimMesh.setColorAt(i, isBorder ? this.borderColor : accent);
      this.underMesh.setColorAt(i, isBorder ? this.borderColor : accent);
    }
    this.trimMesh.instanceColor.needsUpdate = true;
    this.underMesh.instanceColor.needsUpdate = true;
    this.dustMat.color.copy(accent).offsetHSL(0.04, 0, 0.18);
  }

  update(dt, t) {
    this.dust.rotation.y += dt * 0.012;
    this.dust.position.y = Math.sin(t * 0.3) * 0.4;
    for (const p of this.powerObjs) {
      if (!p.group.visible) continue;
      const pulse = 1 + Math.sin(t * 4.4 + p.phase) * 0.16;
      p.core.scale.setScalar(pulse);
      p.halo.scale.setScalar(3.1 * (1 + Math.sin(t * 4.4 + p.phase) * 0.12));
      p.halo.material.opacity = 0.45 + Math.sin(t * 4.4 + p.phase) * 0.18;
    }
    this.pelletMat.color.setHSL(0.52 + Math.sin(t * 1.4) * 0.015, 1, 0.82);
    this.spawnPad.material.opacity = 0.2 + Math.sin(t * 2.2) * 0.08;
  }
}

