import * as THREE from "three";
import { getGlowTexture } from "./textures.js";

const BASE_SPEED = 8.0;
const FRENZY_SPEED = 9.4;
const FIRE_RATE = 0.145;
const FRENZY_FIRE_RATE = 0.075;

const MOUTH_GAPS = [0.16, 0.3, 0.46, 0.64, 0.82, 0.98, 1.12, 1.22];
const CHOMPS = [0.16, 0.46, 0.82, 1.12, 1.22, 1.12, 0.82, 0.46];

function dampAngle(current, target, lambda, dt) {
  let diff = target - current;
  while (diff > Math.PI) diff -= Math.PI * 2;
  while (diff < -Math.PI) diff += Math.PI * 2;
  return current + diff * (1 - Math.exp(-lambda * dt));
}

function makeGun() {
  const gun = new THREE.Group();
  const bodyMat = new THREE.MeshStandardMaterial({
    color: 0x283246,
    metalness: 0.8,
    roughness: 0.28,
    emissive: 0x0b1524,
    emissiveIntensity: 0.7,
  });
  const darkMat = new THREE.MeshStandardMaterial({
    color: 0x111826,
    metalness: 0.7,
    roughness: 0.4,
  });
  const accMat = new THREE.MeshBasicMaterial({ color: 0xffd166 });

  const receiver = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.3, 0.62), bodyMat);
  receiver.position.set(0, 0, 0.22);
  receiver.castShadow = false;
  gun.add(receiver);

  const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 0.52, 8), darkMat);
  barrel.rotation.x = Math.PI / 2;
  barrel.position.set(0, 0.03, 0.72);
  gun.add(barrel);

  const grip = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.34, 0.2), darkMat);
  grip.position.set(0, -0.26, 0.08);
  grip.rotation.x = -0.28;
  gun.add(grip);

  const rail = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.06, 0.35), darkMat);
  rail.position.set(0, 0.19, 0.26);
  gun.add(rail);

  const sight = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.08, 0.05), accMat);
  sight.position.set(0, 0.25, 0.4);
  gun.add(sight);

  const muzzle = new THREE.Mesh(new THREE.TorusGeometry(0.09, 0.025, 6, 12), accMat);
  muzzle.position.set(0, 0.03, 0.98);
  gun.add(muzzle);

  const marker = new THREE.Object3D();
  marker.position.set(0, 0.03, 1.08);
  gun.add(marker);

  return { group: gun, marker, muzzleRing: muzzle };
}

export class Player {
  constructor(scene, maze) {
    this.scene = scene;
    this.maze = maze;
    this.radius = 0.72;
    this.maxHp = 3;
    this.hp = 3;
    this.pos = maze.playerSpawn.clone();
    this.vel = new THREE.Vector3();
    this.aim = new THREE.Vector3(0, 0, 1);
    this.facing = 0;
    this.invuln = 0;
    this.frenzy = false;
    this.fireCd = 0;
    this.gunIndex = 0;
    this.chomp = 0;
    this.hurtFlash = 0;
    this.recoil = [0, 0];
    this.alive = true;
    this._v = new THREE.Vector3();
    this._muzzle = new THREE.Vector3();

    this._build();
    this.reset();
  }

  _build() {
    this.group = new THREE.Group();
    this.scene.add(this.group);

    this.pivot = new THREE.Group();
    this.group.add(this.pivot);

    this.geoms = MOUTH_GAPS.map(
      (gap) =>
        new THREE.SphereGeometry(
          1,
          40,
          26,
          Math.PI / 2 + gap / 2,
          Math.PI * 2 - gap
        )
    );
    this.chompGeoms = CHOMPS.map(
      (gap) =>
        new THREE.SphereGeometry(
          1,
          40,
          26,
          Math.PI / 2 + gap / 2,
          Math.PI * 2 - gap
        )
    );

    this.bodyMat = new THREE.MeshStandardMaterial({
      color: 0xffd400,
      emissive: 0xffb300,
      emissiveIntensity: 0.38,
      roughness: 0.3,
      metalness: 0.18,
    });
    this.body = new THREE.Mesh(this.geoms[0], this.bodyMat);
    this.body.position.y = 1.08;
    this.pivot.add(this.body);

    const eyeWhite = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const eyeBlack = new THREE.MeshBasicMaterial({ color: 0x090d18 });
    const eyeGeo = new THREE.SphereGeometry(0.17, 14, 10);
    const pupilGeo = new THREE.SphereGeometry(0.075, 10, 8);
    this.eyes = [];
    for (const side of [-1, 1]) {
      const white = new THREE.Mesh(eyeGeo, eyeWhite);
      white.position.set(side * 0.32, 1.44, 0.76);
      white.scale.set(0.92, 1.12, 0.62);
      const pupil = new THREE.Mesh(pupilGeo, eyeBlack);
      pupil.position.set(side * 0.34, 1.46, 0.88);
      this.pivot.add(white, pupil);
      this.eyes.push(white, pupil);
    }

    this.gunRig = new THREE.Group();
    this.gunRig.position.y = 0;
    this.pivot.add(this.gunRig);
    this.guns = [];
    for (const side of [-1, 1]) {
      const gun = makeGun();
      gun.group.position.set(side * 0.86, 1.0, 0.28);
      gun.group.rotation.z = side * -0.06;
      gun.baseZ = 0.28;
      gun.side = side;
      this.gunRig.add(gun.group);
      this.guns.push(gun);
    }

    this.shadow = new THREE.Mesh(
      new THREE.CircleGeometry(1.12, 28),
      new THREE.MeshBasicMaterial({
        color: 0x000000,
        transparent: true,
        opacity: 0.34,
        depthWrite: false,
      })
    );
    this.shadow.rotation.x = -Math.PI / 2;
    this.shadow.position.y = 0.025;
    this.group.add(this.shadow);

    this.aura = new THREE.Mesh(
      new THREE.RingGeometry(1.18, 1.46, 48),
      new THREE.MeshBasicMaterial({
        color: 0x34ecff,
        transparent: true,
        opacity: 0.7,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
      })
    );
    this.aura.rotation.x = -Math.PI / 2;
    this.aura.position.y = 0.07;
    this.aura.visible = false;
    this.group.add(this.aura);

    this.auraSprite = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: getGlowTexture(),
        color: 0xffd400,
        transparent: true,
        opacity: 0.2,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      })
    );
    this.auraSprite.scale.setScalar(5.2);
    this.auraSprite.position.y = 1.15;
    this.auraSprite.visible = false;
    this.group.add(this.auraSprite);
  }

  reset() {
    this.pos.copy(this.maze.playerSpawn);
    this.vel.set(0, 0, 0);
    this.aim.set(0, 0, 1);
    this.facing = 0;
    this.hp = this.maxHp;
    this.invuln = 0;
    this.frenzy = false;
    this.fireCd = 0;
    this.alive = true;
    this.hurtFlash = 0;
    this.recoil[0] = 0;
    this.recoil[1] = 0;
    this.group.visible = true;
    this.pivot.visible = true;
    this.aura.visible = false;
    this.auraSprite.visible = false;
    this.group.position.set(this.pos.x, 0, this.pos.z);
    this.pivot.rotation.y = 0;
    this.body.geometry = this.geoms[0];
    this.bodyMat.color.set(0xffd400);
    this.bodyMat.emissive.set(0xffb300);
    this.bodyMat.emissiveIntensity = 0.38;
    this.body.visible = true;
    for (const gun of this.guns) gun.group.visible = true;
    for (const e of this.eyes) e.visible = true;
  }

  setFrenzy(on) {
    this.frenzy = on;
    this.aura.visible = on;
    this.auraSprite.visible = on;
    if (!on) {
      this.bodyMat.color.set(0xffd400);
      this.bodyMat.emissive.set(0xffb300);
    }
  }

  heal(n) {
    this.hp = Math.min(this.maxHp, this.hp + n);
  }

  damage() {
    if (this.invuln > 0 || !this.alive) return false;
    this.hp -= 1;
    this.invuln = 1.75;
    this.hurtFlash = 0.22;
    if (this.hp <= 0) {
      this.hp = 0;
      this.alive = false;
      this.group.visible = false;
    }
    return true;
  }

  tryFire(targets) {
    if (this.fireCd > 0 || !this.alive) return null;
    this.fireCd = this.frenzy ? FRENZY_FIRE_RATE : FIRE_RATE;
    const gun = this.guns[this.gunIndex];
    this.gunIndex = (this.gunIndex + 1) % 2;
    this.recoil[this.guns.indexOf(gun)] = 1;
    this.group.updateMatrixWorld(true);
    gun.marker.getWorldPosition(this._muzzle);
    const dir = this._v.copy(this.aim).setY(0).normalize().clone();
    return { pos: this._muzzle.clone(), dir, muzzle: this._muzzle.clone(), side: gun.side };
  }

  update(dt, move, aimDir, maze, t) {
    if (!this.alive) return;
    this.invuln = Math.max(0, this.invuln - dt);
    this.fireCd = Math.max(0, this.fireCd - dt);
    this.hurtFlash = Math.max(0, this.hurtFlash - dt);

    const speed = this.frenzy ? FRENZY_SPEED : BASE_SPEED;
    const targetVX = move.x * speed;
    const targetVZ = move.y * speed;
    const smoothing = 1 - Math.exp(-15 * dt);
    this.vel.x += (targetVX - this.vel.x) * smoothing;
    this.vel.z += (targetVZ - this.vel.z) * smoothing;
    if (Math.abs(this.vel.x) < 0.01) this.vel.x = 0;
    if (Math.abs(this.vel.z) < 0.01) this.vel.z = 0;

    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    maze.resolveCircle(this.pos, this.radius);

    this.group.position.set(this.pos.x, 0, this.pos.z);

    if (aimDir && (aimDir.x !== 0 || aimDir.z !== 0)) {
      this.aim.copy(aimDir).setY(0).normalize();
    }
    const targetAngle = Math.atan2(this.aim.x, this.aim.z);
    this.facing = dampAngle(this.facing, targetAngle, 16, dt);
    this.pivot.rotation.y = this.facing;

    const spd = Math.hypot(this.vel.x, this.vel.z);
    this.chomp += dt * (spd > 0.6 ? 7.5 + spd * 1.15 : 1.8);
    let idx;
    if (spd > 0.6) {
      const phase = (this.chomp * 0.55) % CHOMPS.length;
      idx = Math.floor(phase) % CHOMPS.length;
    } else {
      idx = 0;
    }
    const geo = this.chompGeoms[idx];
    if (this.body.geometry !== geo) this.body.geometry = geo;

    this.body.position.y = 1.08 + Math.sin(this.chomp * 2) * 0.035;
    this.body.rotation.z = Math.sin(this.chomp * 0.9) * 0.04;
    this.body.rotation.x = -Math.min(0.16, spd * 0.012);

    for (let i = 0; i < this.guns.length; i++) {
      const gun = this.guns[i];
      this.recoil[i] = Math.max(0, this.recoil[i] - dt * 8);
      const kick = this.recoil[i] * this.recoil[i];
      gun.group.position.z = gun.baseZ - kick * 0.17;
      gun.group.rotation.x = -kick * 0.14;
      gun.muzzleRing.material.color.setHex(this.frenzy ? 0x34ecff : 0xffd166);
    }

    if (this.frenzy) {
      this.aura.rotation.z += dt * 1.6;
      const pulse = 1 + Math.sin(t * 7) * 0.12;
      this.aura.scale.setScalar(pulse);
      this.aura.material.opacity = 0.45 + Math.sin(t * 8) * 0.2;
      this.auraSprite.material.opacity = 0.15 + Math.sin(t * 6) * 0.06;
      this.bodyMat.emissive.setHex(0xffa200);
      this.bodyMat.emissiveIntensity = 0.7 + Math.sin(t * 10) * 0.18;
    } else if (this.hurtFlash > 0) {
      this.bodyMat.emissive.setHex(0xff2038);
      this.bodyMat.emissiveIntensity = 1.4;
    } else {
      this.bodyMat.emissive.setHex(0xffb300);
      this.bodyMat.emissiveIntensity = 0.38;
    }

    const blink = this.invuln > 0 ? Math.floor(this.invuln * 14) % 2 === 0 : true;
    this.body.visible = blink;
    for (const e of this.eyes) e.visible = blink;
    for (const gun of this.guns) gun.group.visible = blink;
  }
}

import * as THREE from "three";
import { getGlowTexture } from "./textures.js";

const COLORS = [
  0xff2e63, 0xff6bd6, 0x2ee6ff, 0xffa62e,
  0x7dff6b, 0xb06bff, 0x5b8cff, 0xfff05b,
];
const FLEE_COLOR = new THREE.Color(0x2a3cff);
const FLEE_FLASH = new THREE.Color(0xdce8ff);
const WHITE = new THREE.Color(0xffffff);

function dampAngle(current, target, lambda, dt) {
  let diff = target - current;
  while (diff > Math.PI) diff -= Math.PI * 2;
  while (diff < -Math.PI) diff += Math.PI * 2;
  return current + diff * (1 - Math.exp(-lambda * dt));
}

class Ghost {
  constructor(scene, maze, index) {
    this.scene = scene;
    this.maze = maze;
    this.index = index;
    this.baseColor = new THREE.Color(COLORS[index % COLORS.length]);
    this.color = this.baseColor.clone();

    this.pos = new THREE.Vector3();
    this.path = [];
    this.pathTimer = 0;
    this.pathInterval = 0.3;
    this.active = false;
    this.dead = true;
    this.flee = false;
    this.fleeTime = 0;
    this.flash = 0;
    this.spawnProtect = 0;
    this.scale = 0;
    this.respawnTimer = 0;
    this.speed = 4;
    this.hp = 2;
    this.maxHp = 2;
    this.orbTimer = 3;
    this.phase = Math.random() * Math.PI * 2;
    this.facing = 0;
    this._tmp = new THREE.Vector3();

    this._build();
  }

  _build() {
    this.group = new THREE.Group();
    this.scene.add(this.group);

    this.mat = new THREE.MeshStandardMaterial({
      color: this.baseColor,
      emissive: this.baseColor,
      emissiveIntensity: 0.42,
      roughness: 0.34,
      metalness: 0.08,
    });

    this.body = new THREE.Mesh(new THREE.SphereGeometry(0.82, 22, 16), this.mat);
    this.body.scale.set(1, 1.04, 1);
    this.body.position.y = 1.08;
    this.group.add(this.body);

    this.skirt = new THREE.Mesh(
      new THREE.CylinderGeometry(0.82, 0.74, 0.9, 22, 1, true),
      this.mat
    );
    this.skirt.position.y = 0.54;
    this.group.add(this.skirt);

    const footGeo = new THREE.SphereGeometry(0.21, 10, 8);
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * Math.PI * 2;
      const foot = new THREE.Mesh(footGeo, this.mat);
      foot.position.set(Math.cos(a) * 0.6, 0.13, Math.sin(a) * 0.6);
      foot.scale.y = 1.15;
      this.group.add(foot);
    }

    const whiteMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    this.pupilMat = new THREE.MeshBasicMaterial({ color: 0x0a0f22 });
    const eyeGeo = new THREE.SphereGeometry(0.21, 14, 10);
    const pupilGeo = new THREE.SphereGeometry(0.1, 10, 8);
    for (const side of [-1, 1]) {
      const eye = new THREE.Mesh(eyeGeo, whiteMat);
      eye.position.set(side * 0.28, 1.3, 0.67);
      eye.scale.set(0.92, 1.15, 0.7);
      const pupil = new THREE.Mesh(pupilGeo, this.pupilMat);
      pupil.position.set(side * 0.3, 1.28, 0.82);
      this.group.add(eye, pupil);
    }

    this.halo = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: getGlowTexture(),
        color: this.baseColor,
        transparent: true,
        opacity: 0.16,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      })
    );
    this.halo.scale.setScalar(3.2);
    this.halo.position.y = 1.1;
    this.group.add(this.halo);

    this.group.visible = false;
  }

  reset(spawn, level, spawnIndex) {
    this.pos.copy(spawn);
    this.active = true;
    this.dead = false;
    this.flee = false;
    this.fleeTime = 0;
    this.flash = 0;
    this.path = [];
    this.pathTimer = 0.1 + Math.random() * 0.2;
    this.spawnProtect = 1.37 + Math.random() * 0.4;
    this.scale = 0;
    this.facing = Math.random() * Math.PI * 2;
    this.orbTimer = 3 + Math.random() * 4;
    this.speed = Math.min(6.9, 4.05 + level * 0.24 + (spawnIndex % 3) * 0.14);
    this.maxHp = 2 + Math.min(2, Math.floor((level - 1) / 3)) + (spawnIndex % 4 === 3 ? 1 : 0);
    this.hp = this.maxHp;
    this.pathInterval = 0.3;

    this.group.visible = true;
    this.group.scale.setScalar(0.01);
    this.group.position.set(this.pos.x, 0, this.pos.z);
    this.mat.color.copy(this.baseColor);
    this.mat.emissive.copy(this.baseColor);
    this.mat.emissiveIntensity = 0.42;
    this.pupilMat.color.setHex(0x0a0f22);
    this.halo.material.color.copy(this.baseColor);
    this.halo.material.opacity = 0.16;
  }

  setFlee(on) {
    if (this.flee === on) return;
    this.flee = on;
    this.fleeTime = 0;
    this.pathTimer = 0;
    this.pathInterval = on ? 0.55 : 0.3;
    if (on) {
      this.speed = Math.max(3.3, this.speed * 0.82);
    } else {
      this.speed = Math.min(6.9, this.speed / 0.82);
      this.mat.color.copy(this.baseColor);
      this.mat.emissive.copy(this.baseColor);
      this.mat.emissiveIntensity = 0.42;
      this.pupilMat.color.setHex(0x0a0f22);
      this.halo.material.color.copy(this.baseColor);
    }
  }

  hit(dmg, dir) {
    if (!this.active || this.dead) return false;
    this.hp -= dmg;
    this.flash = 0.14;
    this.spawnProtect = 0;
    if (dir) {
      this.pos.x += dir.x * 0.42;
      this.pos.z += dir.z * 0.42;
      this.maze.resolveCircle(this.pos, 0.6);
    }
    this.pathTimer = 0;
    if (this.hp <= 0) {
      this.die();
      return true;
    }
    return false;
  }

  die() {
    this.active = false;
    this.dead = true;
    this.group.visible = false;
    this.respawnTimer = 4.6 + Math.random() * 2.4;
  }

  respawn(spawn) {
    this.pos.copy(spawn);
    this.active = true;
    this.dead = false;
    this.hp = this.maxHp;
    this.spawnProtect = 1.5;
    this.scale = 0.01;
    this.path = [];
    this.pathTimer = 0;
    this.orbTimer = 2.5 + Math.random() * 3;
    this.group.visible = true;
    this.mat.color.copy(this.flee ? FLEE_COLOR : this.baseColor);
    this.mat.emissive.copy(this.flee ? FLEE_COLOR : this.baseColor);
    this.pathInterval = this.flee ? 0.55 : 0.3;
  }

  update(dt, t, playerPos, maze, level, manager) {
    if (!this.active) {
      return;
    }
    this.spawnProtect = Math.max(0, this.spawnProtect - dt);
    this.flash = Math.max(0, this.flash - dt);
    this.scale += (1 - this.scale) * Math.min(1, dt * 9);
    if (this.scale > 0.995) this.scale = 1;

    this.pathTimer -= dt;
    if (this.pathTimer <= 0) {
      this.pathTimer = this.pathInterval * (0.8 + Math.random() * 0.4);
      this._repath(playerPos, maze);
    }

    let target;
    let direct = false;
    if (this.path.length > 0) {
      const cell = this.path[0];
      target = maze.cellToWorld(cell.x, cell.y, this._tmp);
      const dx = target.x - this.pos.x;
      const dz = target.z - this.pos.z;
      if (dx * dx + dz * dz < 0.08) {
        this.path.shift();
        if (this.path.length > 0) {
          const n = this.path[0];
          target = maze.cellToWorld(n.x, n.y, this._tmp);
        }
      }
    } else {
      target = this._tmp.copy(playerPos);
      direct = true;
    }

    let dx = target.x - this.pos.x;
    let dz = target.z - this.pos.z;
    const dist = Math.hypot(dx, dz);
    if (dist > 0.0001) {
      dx /= dist;
      dz /= dist;
    }

    // Group separation so packs fan out instead of stacking.
    let sepX = 0;
    let sepZ = 0;
    for (const other of manager.ghosts) {
      if (other === this || !other.active) continue;
      const ox = this.pos.x - other.pos.x;
      const oz = this.pos.z - other.pos.z;
      const d2 = ox * ox + oz * oz;
      if (d2 > 0.0001 && d2 < 2.4) {
        const d = Math.sqrt(d2);
        const push = (1.55 - d) * 0.75;
        sepX += (ox / d) * push;
        sepZ += (oz / d) * push;
      }
    }

    const speed = this.speed * (this.flee ? 0.94 : 1);
    const step = speed * dt;
    this.pos.x += (dx + sepX) * step;
    this.pos.z += (dz + sepZ) * step;
    maze.resolveCircle(this.pos, 0.62);

    if (dist > 0.25 || this.flee) {
      const targetAngle = this.flee
        ? Math.atan2(dx, dz)
        : Math.atan2(playerPos.x - this.pos.x, playerPos.z - this.pos.z);
      this.facing = dampAngle(this.facing, targetAngle, 9, dt);
    }

    const bob = Math.sin(t * 3.4 + this.phase) * 0.07;
    this.group.position.set(this.pos.x, 0.03 + bob, this.pos.z);
    this.group.rotation.y = this.facing;
    this.group.scale.setScalar(this.scale);

    // eyes / flash colours
    if (this.flash > 0) {
      this.mat.color.copy(WHITE);
      this.mat.emissive.copy(WHITE);
      this.mat.emissiveIntensity = 2.2;
    } else if (this.flee) {
      this.fleeTime += dt;
      const on = Math.floor(this.fleeTime * 8) % 2 === 0;
      this.mat.color.copy(on ? FLEE_FLASH : FLEE_COLOR);
      this.mat.emissive.copy(on ? FLEE_FLASH : FLEE_COLOR);
      this.mat.emissiveIntensity = 0.85;
      this.pupilMat.color.setHex(0xdce8ff);
      this.halo.material.color.copy(FLEE_COLOR);
    } else {
      this.mat.color.copy(this.baseColor);
      this.mat.emissive.copy(this.baseColor);
      this.mat.emissiveIntensity = 0.42 + Math.sin(t * 2 + this.phase) * 0.08;
      this.pupilMat.color.setHex(0x0a0f22);
      this.halo.material.color.copy(this.baseColor);
    }
    this.halo.material.opacity = this.flee ? 0.34 : 0.16;

    // Spitters start at sector 2. They only shoot with a clear lane.
    if (!this.flee && level >= 2 && this.spawnProtect <= 0 && dist < 17) {
      this.orbTimer -= dt;
      if (this.orbTimer <= 0) {
        const toPlayer = this._tmp
          .copy(playerPos)
          .sub(this.pos);
        toPlayer.y = 0;
        if (maze.hasLineOfSight(this.pos, playerPos)) {
          const len = toPlayer.length();
          if (len > 0.1) {
            toPlayer.multiplyScalar(1 / len);
            manager.shoot({
              x: this.pos.x,
              z: this.pos.z,
              y: 1.15,
              dirX: toPlayer.x,
              dirZ: toPlayer.z,
            });
          }
        }
        this.orbTimer = Math.max(2.6, 5.2 - level * 0.18) + Math.random() * 2.6;
      }
    }
  }

  _repath(playerPos, maze) {
    const cell = maze.worldToCell(this.pos.x, this.pos.z);
    let target;
    if (this.flee) {
      target = maze.farthestCorner(playerPos);
    } else {
      target = maze.worldToCell(playerPos.x, playerPos.z);
    }
    this.path = maze.findPath(cell.x, cell.y, target.x, target.y);
    if (this.path.length > 1 && Math.random() < 0.25) this.path.shift();
  }

  get worldPos() {
    return new THREE.Vector3(this.pos.x, 1.05, this.pos.z);
  }
}

export class GhostManager {
  constructor(scene, maze) {
    this.maze = maze;
    this.ghosts = [];
    for (let i = 0; i < 8; i++) this.ghosts.push(new Ghost(scene, maze, i));
    this.level = 1;
    this.shoot = () => {};
    this.initialSpawns = false;
  }

  reset(level) {
    this.level = level;
    const count = Math.min(8, 3 + level);
    for (let i = 0; i < this.ghosts.length; i++) {
      const ghost = this.ghosts[i];
      if (i < count) {
        const spawn =
          this.maze.ghostSpawns[i % this.maze.ghostSpawns.length] ||
          this.maze.centerSpawn;
        ghost.reset(spawn, level, i);
      } else {
        ghost.active = false;
        ghost.dead = true;
        ghost.group.visible = false;
      }
    }
  }

  setFlee(on) {
    for (const g of this.ghosts) g.setFlee(on);
  }

  update(dt, t, playerPos, maze) {
    for (const g of this.ghosts) {
      if (!g.active) {
        if (g.dead) {
          g.respawnTimer -= dt;
          if (g.respawnTimer <= 0) {
            const spawn =
              this.maze.ghostSpawns[Math.floor(Math.random() * this.maze.ghostSpawns.length)] ||
              this.maze.centerSpawn;
            g.respawn(spawn);
          }
        }
        continue;
      }
      g.update(dt, t, playerPos, maze, this.level, this);
    }
  }

  spawnPositions() {
    return this.maze.ghostSpawns;
  }
}

