export class Input {
  constructor(canvas, handlers = {}) {
    this.canvas = canvas;
    this.handlers = handlers;
    this.keys = new Set();
    this.pointer = { x: 0, y: 0, down: false, active: false };
    this.isTouch =
      (window.matchMedia && window.matchMedia("(pointer: coarse)").matches) ||
      navigator.maxTouchPoints > 0;

    if (this.isTouch) document.body.classList.add("touch");

    this.sticks = {
      move: { active: false, id: null, vec: { x: 0, y: 0 }, el: null, knob: null },
      aim: { active: false, id: null, vec: { x: 0, y: 0 }, el: null, knob: null },
    };

    this._bindKeyboard();
    this._bindMouse();
    this._bindStick("move", "stickMove");
    this._bindStick("aim", "stickAim");

    window.addEventListener("blur", () => this.keys.clear());
  }

  _gesture() {
    this.handlers.onGesture?.();
  }

  _bindKeyboard() {
    window.addEventListener("keydown", (e) => {
      const key = e.key.toLowerCase();
      if (
        key === " " ||
        key === "arrowup" ||
        key === "arrowdown" ||
        key === "arrowleft" ||
        key === "arrowright"
      ) {
        e.preventDefault();
      }
      this._gesture();
      if (!e.repeat) {
        if (key === "p" || key === "escape") this.handlers.onPause?.();
        if (key === "m") this.handlers.onMute?.();
        if (key === "enter") this.handlers.onEnter?.();
      }
      this.keys.add(key);
    });

    window.addEventListener("keyup", (e) => {
      this.keys.delete(e.key.toLowerCase());
    });
  }

  _bindMouse() {
    window.addEventListener("pointermove", (e) => {
      if (e.pointerType === "touch") return;
      this.pointer.x = e.clientX;
      this.pointer.y = e.clientY;
      this.pointer.active = true;
    });

    this.canvas.addEventListener("pointerdown", (e) => {
      if (e.pointerType === "touch") {
        document.body.classList.add("touch");
        this.isTouch = true;
        return;
      }
      this._gesture();
      if (e.button === 0) {
        this.pointer.down = true;
        this.pointer.x = e.clientX;
        this.pointer.y = e.clientY;
        this.pointer.active = true;
      }
    });

    window.addEventListener("pointerup", (e) => {
      if (e.pointerType === "touch") return;
      if (e.button === 0) this.pointer.down = false;
    });

    window.addEventListener("pointercancel", () => {
      this.pointer.down = false;
    });

    this.canvas.addEventListener("contextmenu", (e) => e.preventDefault());
  }

  _bindStick(kind, id) {
    const el = document.getElementById(id);
    if (!el) return;
    const knob = el.querySelector(".stick-knob");
    const state = this.sticks[kind];
    state.el = el;
    state.knob = knob;

    const apply = (e) => {
      const rect = el.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const max = rect.width * 0.33;
      let dx = e.clientX - cx;
      let dy = e.clientY - cy;
      const len = Math.hypot(dx, dy);
      if (len > max) {
        dx = (dx / len) * max;
        dy = (dy / len) * max;
      }
      state.vec.x = dx / max;
      state.vec.y = dy / max;
      const dead = 0.12;
      if (Math.abs(state.vec.x) < dead) state.vec.x = 0;
      if (Math.abs(state.vec.y) < dead) state.vec.y = 0;
      knob.style.transform = `translate3d(${dx}px, ${dy}px, 0)`;
    };

    const down = (e) => {
      if (e.pointerType === "mouse" && e.button !== 0) return;
      if (state.id !== null) return;
      document.body.classList.add("touch");
      this.isTouch = true;
      this._gesture();
      state.active = true;
      state.id = e.pointerId;
      el.classList.add("active");
      try {
        el.setPointerCapture(e.pointerId);
      } catch {}
      apply(e);
      e.preventDefault();
    };

    const move = (e) => {
      if (!state.active || e.pointerId !== state.id) return;
      apply(e);
      e.preventDefault();
    };

    const up = (e) => {
      if (e.pointerId !== state.id) return;
      state.active = false;
      state.id = null;
      state.vec.x = 0;
      state.vec.y = 0;
      el.classList.remove("active");
      knob.style.transform = "translate3d(0, 0, 0)";
    };

    el.addEventListener("pointerdown", down);
    el.addEventListener("pointermove", move);
    el.addEventListener("pointerup", up);
    el.addEventListener("pointercancel", up);
    el.addEventListener("lostpointercapture", up);
  }

  getMove(out) {
    let x = 0;
    let y = 0;
    if (this.keys.has("a") || this.keys.has("arrowleft")) x -= 1;
    if (this.keys.has("d") || this.keys.has("arrowright")) x += 1;
    if (this.keys.has("w") || this.keys.has("arrowup")) y -= 1;
    if (this.keys.has("s") || this.keys.has("arrowdown")) y += 1;
    if (this.sticks.move.active) {
      x += this.sticks.move.vec.x;
      y += this.sticks.move.vec.y;
    }
    const len = Math.hypot(x, y);
    if (len > 1) {
      x /= len;
      y /= len;
    }
    out.x = x;
    out.y = y;
    return out;
  }

  /** Returns normalized screen-space aim vector from the right stick, or null. */
  getStickAim(out) {
    const s = this.sticks.aim;
    if (!s.active) return null;
    const len = Math.hypot(s.vec.x, s.vec.y);
    if (len < 0.2) return null;
    out.x = s.vec.x;
    out.y = s.vec.y;
    return out;
  }

  stickFiring() {
    const s = this.sticks.aim;
    if (!s.active) return false;
    return Math.hypot(s.vec.x, s.vec.y) > 0.32;
  }

  firing() {
    return this.keys.has(" ") || this.pointer.down || this.stickFiring();
  }

  keyboardMoveActive() {
    return (
      this.keys.has("w") ||
      this.keys.has("a") ||
      this.keys.has("s") ||
      this.keys.has("d") ||
      this.keys.has("arrowup") ||
      this.keys.has("arrowdown") ||
      this.keys.has("arrowleft") ||
      this.keys.has("arrowright")
    );
  }
}

const STORE_MUTE = "pacstrike.muted";

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.muted = false;
    this.ambience = null;
    this._lastChomp = 0;
    this._chompFlip = 0;
    try {
      this.muted = localStorage.getItem(STORE_MUTE) === "1";
    } catch {
      this.muted = false;
    }
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 22;
    comp.ratio.value = 7;
    comp.attack.value = 0.004;
    comp.release.value = 0.22;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);

    const len = Math.floor(this.ctx.sampleRate * 0.7);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buffer;
  }

  _ok() {
    return this.ctx && this.ctx.state === "running" && !this.muted;
  }

  setMuted(muted) {
    this.muted = muted;
    try {
      localStorage.setItem(STORE_MUTE, muted ? "1" : "0");
    } catch {}
    if (this.master) {
      const t = this.ctx.currentTime;
      this.master.gain.cancelScheduledValues(t);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.5, t, 0.02);
    }
  }

  toggleMuted() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  tone({
    freq = 440,
    end = freq,
    dur = 0.14,
    type = "sine",
    vol = 0.2,
    attack = 0.004,
    delay = 0,
    pan = 0,
  } = {}) {
    if (!this._ok()) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (end !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, end), t0 + dur);
    let node = gain;
    if (pan) {
      const p = ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, pan));
      gain.connect(p);
      p.connect(this.master);
    } else {
      gain.connect(this.master);
    }
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.linearRampToValueAtTime(vol, t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(node);
    osc.start(t0);
    osc.stop(t0 + dur + 0.03);
  }

  noise({
    dur = 0.12,
    vol = 0.16,
    type = "highpass",
    freq = 900,
    end = null,
    delay = 0,
    pan = 0,
  } = {}) {
    if (!this._ok() || !this.noiseBuffer) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = 1;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t0);
    if (end) filter.frequency.exponentialRampToValueAtTime(Math.max(30, end), t0 + dur);
    filter.Q.value = 0.8;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(vol, t0);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter);
    filter.connect(gain);
    if (pan) {
      const p = ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, pan));
      gain.connect(p);
      p.connect(this.master);
    } else {
      gain.connect(this.master);
    }
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  chomp() {
    if (!this._ok()) return;
    const now = this.ctx.currentTime;
    if (now - this._lastChomp < 0.055) return;
    this._lastChomp = now;
    this._chompFlip = (this._chompFlip + 1) % 2;
    const base = this._chompFlip ? 620 : 470;
    this.tone({ freq: base, end: base * 1.7, dur: 0.06, type: "triangle", vol: 0.12 });
    this.tone({ freq: base * 0.5, end: base * 0.7, dur: 0.05, type: "sine", vol: 0.06 });
  }

  shoot(frenzy = false) {
    if (!this._ok()) return;
    const p = (Math.random() - 0.5) * 0.3;
    this.tone({
      freq: frenzy ? 1100 : 880,
      end: frenzy ? 260 : 190,
      dur: frenzy ? 0.075 : 0.09,
      type: "square",
      vol: 0.075,
      pan: p,
    });
    this.noise({ dur: 0.05, vol: 0.05, type: "highpass", freq: 2400, pan: p });
  }

  hit() {
    if (!this._ok()) return;
    this.noise({ dur: 0.06, vol: 0.12, type: "bandpass", freq: 1200, end: 300 });
    this.tone({ freq: 300, end: 160, dur: 0.07, type: "square", vol: 0.06 });
  }

  ghostDie() {
    if (!this._ok()) return;
    this.tone({ freq: 660, end: 70, dur: 0.32, type: "sawtooth", vol: 0.11 });
    this.tone({ freq: 990, end: 120, dur: 0.24, type: "triangle", vol: 0.07, delay: 0.02 });
    this.noise({ dur: 0.3, vol: 0.13, type: "lowpass", freq: 2600, end: 200 });
  }

  eatGhost(chain = 1) {
    if (!this._ok()) return;
    const base = 420 + Math.min(5, chain) * 110;
    for (let i = 0; i < 3; i++) {
      this.tone({
        freq: base * (1 + i * 0.32),
        end: base * (1.25 + i * 0.32),
        dur: 0.09,
        type: "triangle",
        vol: 0.1,
        delay: i * 0.055,
      });
    }
    this.noise({ dur: 0.16, vol: 0.08, type: "highpass", freq: 1800, end: 4000 });
  }

  power() {
    if (!this._ok()) return;
    const notes = [392, 523, 659, 784, 1046];
    notes.forEach((f, i) =>
      this.tone({
        freq: f,
        end: f * 1.02,
        dur: 0.18,
        type: "sawtooth",
        vol: 0.075,
        delay: i * 0.055,
      })
    );
    this.noise({ dur: 0.5, vol: 0.07, type: "highpass", freq: 400, end: 6000 });
  }

  powerEnd() {
    if (!this._ok()) return;
    this.tone({ freq: 520, end: 140, dur: 0.4, type: "triangle", vol: 0.09 });
  }

  hurt() {
    if (!this._ok()) return;
    this.tone({ freq: 180, end: 55, dur: 0.34, type: "sawtooth", vol: 0.2 });
    this.noise({ dur: 0.32, vol: 0.2, type: "lowpass", freq: 1600, end: 180 });
    this.tone({ freq: 90, end: 45, dur: 0.45, type: "sine", vol: 0.2, delay: 0.03 });
  }

  orbFire() {
    if (!this._ok()) return;
    this.tone({ freq: 260, end: 95, dur: 0.28, type: "sawtooth", vol: 0.055 });
    this.tone({ freq: 130, end: 60, dur: 0.32, type: "sine", vol: 0.08, delay: 0.02 });
  }

  orbPop() {
    if (!this._ok()) return;
    this.noise({ dur: 0.12, vol: 0.1, type: "bandpass", freq: 700, end: 2000 });
  }

  levelClear(level = 1) {
    if (!this._ok()) return;
    const scale = [523, 659, 784, 1046, 1318];
    scale.forEach((f, i) => {
      this.tone({
        freq: f,
        dur: 0.22,
        type: "triangle",
        vol: 0.1,
        delay: i * 0.1,
      });
      this.tone({
        freq: f / 2,
        dur: 0.24,
        type: "sine",
        vol: 0.07,
        delay: i * 0.1,
      });
    });
    this.noise({ dur: 0.7, vol: 0.05, type: "highpass", freq: 1200, end: 7000, delay: 0.1 });
  }

  gameOver() {
    if (!this._ok()) return;
    const notes = [392, 330, 262, 196, 131];
    notes.forEach((f, i) =>
      this.tone({
        freq: f,
        end: f * 0.86,
        dur: 0.34,
        type: "sawtooth",
        vol: 0.1,
        delay: i * 0.16,
      })
    );
    this.noise({ dur: 1.1, vol: 0.12, type: "lowpass", freq: 1200, end: 90 });
  }

  click() {
    if (!this._ok()) return;
    this.tone({ freq: 880, end: 1320, dur: 0.05, type: "square", vol: 0.05 });
  }

  startGame() {
    if (!this._ok()) return;
    this.tone({ freq: 196, end: 392, dur: 0.16, type: "sawtooth", vol: 0.08 });
    this.tone({ freq: 523, dur: 0.28, type: "triangle", vol: 0.08, delay: 0.1 });
  }

  heartbeat() {
    if (!this._ok()) return;
    this.tone({ freq: 70, end: 40, dur: 0.18, type: "sine", vol: 0.16 });
    this.tone({ freq: 62, end: 36, dur: 0.16, type: "sine", vol: 0.11, delay: 0.14 });
  }

  startAmbience() {
    if (!this._ok() || this.ambience) return;
    const ctx = this.ctx;
    const group = ctx.createGain();
    group.gain.value = 0;
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 160;
    filter.Q.value = 3;
    const osc1 = ctx.createOscillator();
    osc1.type = "sawtooth";
    osc1.frequency.value = 55;
    const osc2 = ctx.createOscillator();
    osc2.type = "sine";
    osc2.frequency.value = 27.5;
    const g1 = ctx.createGain();
    g1.gain.value = 0.05;
    const g2 = ctx.createGain();
    g2.gain.value = 0.09;
    osc1.connect(g1);
    g1.connect(filter);
    osc2.connect(g2);
    g2.connect(filter);
    filter.connect(group);
    group.connect(this.master);
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.09;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 40;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    osc1.start();
    osc2.start();
    lfo.start();
    group.gain.setTargetAtTime(0.4, ctx.currentTime, 1.2);
    this.ambience = { group, filter, osc1, osc2, lfo, g1, g2 };
    this.setFrenzy(false);
  }

  stopAmbience() {
    if (!this.ambience || !this.ctx) return;
    const a = this.ambience;
    this.ambience = null;
    const t = this.ctx.currentTime;
    a.group.gain.cancelScheduledValues(t);
    a.group.gain.setTargetAtTime(0, t, 0.25);
    setTimeout(() => {
      try {
        a.osc1.stop();
        a.osc2.stop();
        a.lfo.stop();
      } catch {}
    }, 700);
  }

  setFrenzy(on) {
    if (!this.ambience || !this.ctx) return;
    const t = this.ctx.currentTime;
    const a = this.ambience;
    a.filter.frequency.setTargetAtTime(on ? 520 : 160, t, 0.25);
    a.osc1.detune.setTargetAtTime(on ? 40 : 0, t, 0.3);
    a.osc2.detune.setTargetAtTime(on ? -30 : 0, t, 0.3);
    a.g1.gain.setTargetAtTime(on ? 0.075 : 0.05, t, 0.3);
  }
}

const BEST_KEY = "pacstrike.best";

function pad(n, width = 6) {
  return String(Math.max(0, Math.floor(n))).padStart(width, "0");
}

export class UI {
  constructor() {
    this.el = {
      hud: document.getElementById("hud"),
      score: document.getElementById("score"),
      level: document.getElementById("level"),
      dots: document.getElementById("dots"),
      hearts: document.getElementById("hearts"),
      frenzyWrap: document.getElementById("frenzyWrap"),
      frenzyFill: document.getElementById("frenzyFill"),
      menuScreen: document.getElementById("menuScreen"),
      pauseScreen: document.getElementById("pauseScreen"),
      clearScreen: document.getElementById("clearScreen"),
      overScreen: document.getElementById("overScreen"),
      toast: document.getElementById("toast"),
      damage: document.getElementById("damage"),
      crosshair: document.getElementById("crosshair"),
      menuBest: document.getElementById("menuBest"),
      finalScore: document.getElementById("finalScore"),
      finalBest: document.getElementById("finalBest"),
      finalLevel: document.getElementById("finalLevel"),
      finalKills: document.getElementById("finalKills"),
      clearBonus: document.getElementById("clearBonus"),
      clearNext: document.getElementById("clearNext"),
      muteBtn: document.getElementById("muteBtn"),
      pauseBtn: document.getElementById("pauseBtn"),
    };

    this.best = 0;
    try {
      this.best = Number(localStorage.getItem(BEST_KEY) || 0) || 0;
    } catch {}
    this.el.menuBest.textContent = pad(this.best);

    this.lastScore = -1;
    this.lastLevel = -1;
    this.lastDots = -1;
    this.lastHp = -1;
    this.lastMaxHp = -1;
    this.lastFrenzy = -1;
    this.heartEls = [];
    this.toastTimer = null;
    this.damageTimer = null;
    this.currentScreen = "menu";
  }

  bind(handlers) {
    const click = (id, fn) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener("click", (e) => {
        e.preventDefault();
        handlers.onGesture?.();
        fn();
      });
    };
    click("startBtn", () => handlers.onStart?.());
    click("resumeBtn", () => handlers.onResume?.());
    click("restartBtn", () => handlers.onRestart?.());
    click("restartBtnPause", () => handlers.onRestart?.());
    click("menuBtn", () => handlers.onMenu?.());
    click("quitBtn", () => handlers.onMenu?.());
    this.el.pauseBtn.addEventListener("click", (e) => {
      e.preventDefault();
      handlers.onGesture?.();
      handlers.onPause?.();
    });
    this.el.muteBtn.addEventListener("click", (e) => {
      e.preventDefault();
      handlers.onGesture?.();
      handlers.onMute?.();
    });
  }

  setMuted(muted) {
    this.el.muteBtn.classList.toggle("muted", muted);
    this.el.muteBtn.setAttribute("aria-label", muted ? "Unmute sound" : "Mute sound");
  }

  setBest(best) {
    this.best = Math.max(this.best, Math.floor(best));
    this.el.menuBest.textContent = pad(this.best);
    try {
      localStorage.setItem(BEST_KEY, String(this.best));
    } catch {}
  }

  update(state) {
    const { score, level, pellets, hp, maxHp, frenzy, frenzyMax } = state;
    if (score !== this.lastScore) {
      this.el.score.textContent = pad(score);
      this.lastScore = score;
    }
    if (level !== this.lastLevel) {
      this.el.level.textContent = `LV ${pad(level, 2)}`;
      this.lastLevel = level;
    }
    if (pellets !== this.lastDots) {
      this.el.dots.textContent = `DOTS ${pad(pellets, 3)}`;
      this.lastDots = pellets;
    }
    if (hp !== this.lastHp || maxHp !== this.lastMaxHp) {
      this._renderHearts(hp, maxHp);
      this.lastHp = hp;
      this.lastMaxHp = maxHp;
    }
    const f = frenzyMax > 0 ? Math.max(0, frenzy) / frenzyMax : 0;
    if (Math.abs(f - this.lastFrenzy) > 0.005 || (frenzy <= 0 && this.lastFrenzy > 0)) {
      this.el.frenzyFill.style.transform = `scaleX(${f.toFixed(4)})`;
      this.el.frenzyWrap.classList.toggle("active", frenzy > 0);
      this.lastFrenzy = f;
    }
  }

  _renderHearts(hp, maxHp) {
    this.el.hearts.innerHTML = "";
    this.heartEls = [];
    for (let i = 0; i < maxHp; i++) {
      const span = document.createElement("span");
      span.textContent = "\u2665";
      span.className = i < hp ? "" : "empty";
      this.el.hearts.appendChild(span);
      this.heartEls.push(span);
    }
    this.el.hearts.setAttribute("aria-label", `${hp} of ${maxHp} lives`);
  }

  popHeart() {
    const full = this.heartEls.find((h) => !h.classList.contains("empty"));
    if (!full) return;
    full.classList.remove("pop");
    void full.offsetWidth;
    full.classList.add("pop");
  }

  showScreen(name) {
    this.currentScreen = name;
    this.el.menuScreen.classList.toggle("hidden", name !== "menu");
    this.el.pauseScreen.classList.toggle("hidden", name !== "pause");
    this.el.clearScreen.classList.toggle("hidden", name !== "clear");
    this.el.overScreen.classList.toggle("hidden", name !== "over");
    this.el.hud.classList.toggle("hidden", name === "menu");
    document.body.classList.toggle("in-menu", name === "menu");
  }

  showClear(level, bonus) {
    this.el.clearBonus.textContent = `+${bonus}`;
    this.el.clearNext.textContent = `LV ${pad(level + 1, 2)}`;
    this.showScreen("clear");
  }

  showOver(stats) {
    this.el.finalScore.textContent = pad(stats.score);
    this.el.finalBest.textContent = pad(stats.best);
    this.el.finalLevel.textContent = pad(stats.level, 2);
    this.el.finalKills.textContent = String(stats.kills);
    this.showScreen("over");
  }

  toast(text, kind = "", duration = 1500) {
    const el = this.el.toast;
    el.textContent = text;
    el.classList.remove("show", "danger", "cool");
    if (kind) el.classList.add(kind);
    void el.offsetWidth;
    el.classList.add("show");
    if (this.toastTimer) clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => {
      el.classList.remove("show");
      this.toastTimer = null;
    }, duration);
  }

  flashDamage() {
    const el = this.el.damage;
    el.classList.remove("hit");
    void el.offsetWidth;
    el.classList.add("hit");
    if (this.damageTimer) clearTimeout(this.damageTimer);
    this.damageTimer = setTimeout(() => {
      el.classList.remove("hit");
      this.damageTimer = null;
    }, 520);
  }

  crosshair(x, y, visible, firing) {
    if (document.body.classList.contains("touch")) return;
    const el = this.el.crosshair;
    el.style.left = `${x}px`;
    el.style.top = `${y}px`;
    el.classList.toggle("show", visible);
    el.classList.toggle("fire", firing);
  }
}

import * as THREE from "three";
import { Maze } from "./world.js";
import { Player } from "./player.js";
import { GhostManager } from "./ghosts.js";
import { FX } from "./fx.js";
import { UI } from "./ui.js";
import { Input } from "./input.js";
import { AudioEngine } from "./audio.js";
import { getGlowTexture } from "./textures.js";

const STATE = {
  MENU: "menu",
  PLAYING: "playing",
  PAUSED: "paused",
  DYING: "dying",
  CLEARED: "cleared",
  OVER: "over",
};

const BULLET_COUNT = 72;
const ORB_COUNT = 32;
const BULLET_SPEED = 44;
const ORB_SPEED = 7.2;
const FRENZY_BASE = 8.2;

function pad(n, w = 2) {
  return String(n).padStart(w, "0");
}

function segmentDist2(ax, az, bx, bz, cx, cz) {
  const abx = bx - ax;
  const abz = bz - az;
  const acx = cx - ax;
  const acz = cz - az;
  const len2 = abx * abx + abz * abz;
  let t = len2 > 0 ? (acx * abx + acz * abz) / len2 : 0;
  t = Math.max(0, Math.min(1, t));
  const px = ax + abx * t - cx;
  const pz = az + abz * t - cz;
  return px * px + pz * pz;
}

class Game {
  constructor() {
    this.canvas = document.getElementById("scene");
    this.isTouch =
      (window.matchMedia && window.matchMedia("(pointer: coarse)").matches) ||
      navigator.maxTouchPoints > 0;

    this.state = STATE.MENU;
    this.time = 0;
    this.menuTime = 0;
    this.stateTimer = 0;
    this.score = 0;
    this.level = 1;
    this.combo = 0;
    this.kills = 0;
    this.frenzy = 0;
    this.frenzyMax = FRENZY_BASE;
    this.best = 0;
    this.heartTimer = 0;

    this._move = { x: 0, y: 0 };
    this._stickAim = { x: 0, y: 0 };
    this._aimDir = new THREE.Vector3(0, 0, 1);
    this._aimPoint = new THREE.Vector3();
    this._aimFallback = new THREE.Vector3(0, 0, 1);
    this._ndc = new THREE.Vector2(0, 0);
    this._desired = new THREE.Vector3();
    this._look = new THREE.Vector3();
    this._cameraLook = new THREE.Vector3();
    this._tmp = new THREE.Vector3();
    this._prev = new THREE.Vector3();

    this._initRenderer();
    this._initScene();

    this.audio = new AudioEngine();
    this.ui = new UI();
    this.input = new Input(this.canvas, {
      onPause: () => this.togglePause(),
      onMute: () => this.toggleMute(),
      onEnter: () => this.handleEnter(),
      onGesture: () => this.audio.init(),
    });
    this.isTouch = this.input.isTouch;

    this.maze = new Maze(this.scene);
    this.player = new Player(this.scene, this.maze);
    this.fx = new FX(this.scene, this.camera, document.getElementById("popups"));
    this.ghosts = new GhostManager(this.scene, this.maze);
    this.ghosts.shoot = (spec) => this.spawnOrb(spec);

    this._buildBullets();
    this._buildOrbs();
    this._bindUI();
    this._resetWorld();
    this._resize();

    this.ui.setMuted(this.audio.muted);
    this.ui.showScreen("menu");
    this.camera.position.set(0, 26, 34);
    this.camera.lookAt(0, 0, 0);
    this._cameraLook.set(0, 0, 0);
    this.playerLight.position.copy(this.player.pos).setY(3);

    window.addEventListener("resize", () => this._resize());
    window.addEventListener("orientationchange", () => setTimeout(() => this._resize(), 120));
    document.addEventListener("visibilitychange", () => {
      if (document.hidden && this.state === STATE.PLAYING) this.pause();
    });

    this.clock = new THREE.Clock();
    this._loop = this._loop.bind(this);
    requestAnimationFrame(this._loop);
  }

  _initRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: "high-performance",
      alpha: false,
    });
    this.renderer.setPixelRatio(
      Math.min(window.devicePixelRatio || 1, this.isTouch ? 1.5 : 2)
    );
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.18;
    this.renderer.setClearColor(0x03040c, 1);
  }

  _initScene() {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x03040c);
    this.scene.fog = new THREE.FogExp2(0x03040c, 0.0085);

    this.camera = new THREE.PerspectiveCamera(52, 1, 0.1, 180);
    this.camera.position.set(0, 26, 34);
    this.camera.lookAt(0, 0, 0);

    const hemi = new THREE.HemisphereLight(0x4a7dff, 0x05060d, 1.15);
    this.scene.add(hemi);

    const key = new THREE.DirectionalLight(0xfff1cf, 2.1);
    key.position.set(20, 32, 12);
    this.scene.add(key);

    const rim = new THREE.DirectionalLight(0x2d7bff, 1.0);
    rim.position.set(-18, 14, -24);
    this.scene.add(rim);

    const centerGlow = new THREE.PointLight(0x34ecff, 65, 34, 2);
    centerGlow.position.set(0, 9, 0);
    this.scene.add(centerGlow);

    this.playerLight = new THREE.PointLight(0xffd400, 26, 13, 2);
    this.playerLight.position.set(0, 3, 0);
    this.scene.add(this.playerLight);
  }

  _buildBullets() {
    const geo = new THREE.CapsuleGeometry(0.055, 0.62, 3, 6);
    geo.rotateX(Math.PI / 2);
    const mat = new THREE.MeshBasicMaterial({ color: 0xfff3b0 });
    const glowMat = new THREE.SpriteMaterial({
      map: getGlowTexture(),
      color: 0xffc94d,
      transparent: true,
      opacity: 0.7,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    this.bullets = [];
    for (let i = 0; i < BULLET_COUNT; i++) {
      const mesh = new THREE.Mesh(geo, mat);
      mesh.visible = false;
      mesh.frustumCulled = false;
      const glow = new THREE.Sprite(glowMat);
      glow.scale.setScalar(1.25);
      mesh.add(glow);
      this.scene.add(mesh);
      this.bullets.push({
        mesh,
        active: false,
        life: 0,
        dir: new THREE.Vector3(),
        vel: new THREE.Vector3(),
      });
    }
    this.bulletCursor = 0;
  }

  _buildOrbs() {
    const geo = new THREE.SphereGeometry(0.23, 12, 10);
    const mat = new THREE.MeshBasicMaterial({ color: 0xff4fd8 });
    const glowMat = new THREE.SpriteMaterial({
      map: getGlowTexture(),
      color: 0xff3fbe,
      transparent: true,
      opacity: 0.85,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    this.orbs = [];
    for (let i = 0; i < ORB_COUNT; i++) {
      const mesh = new THREE.Mesh(geo, mat);
      const glow = new THREE.Sprite(glowMat);
      glow.scale.setScalar(2.1);
      mesh.add(glow);
      mesh.visible = false;
      mesh.frustumCulled = false;
      this.scene.add(mesh);
      this.orbs.push({
        mesh,
        active: false,
        life: 0,
        phase: Math.random() * 6.28,
        dir: new THREE.Vector3(),
      });
    }
    this.orbCursor = 0;
  }

  _bindUI() {
    this.ui.bind({
      onStart: () => this.startRun(),
      onResume: () => this.resume(),
      onRestart: () => this.startRun(),
      onMenu: () => this.goMenu(),
      onPause: () => this.togglePause(),
      onMute: () => this.toggleMute(),
      onGesture: () => this.audio.init(),
    });
  }

  _resetWorld() {
    this.maze.resetPellets(1);
    this.player.reset();
    this.ghosts.reset(1);
    this.fx.clear();
    for (const b of this.bullets) {
      b.active = false;
      b.mesh.visible = false;
    }
    for (const o of this.orbs) {
      o.active = false;
      o.mesh.visible = false;
    }
    this.score = 0;
    this.level = 1;
    this.combo = 0;
    this.kills = 0;
    this.frenzy = 0;
    this.frenzyMax = FRENZY_BASE;
    this.player.setFrenzy(false);
    this.ghosts.setFlee(false);
    this.ui.update({
      score: 0,
      level: 1,
      pellets: this.maze.pelletsLeft,
      hp: this.player.maxHp,
      maxHp: this.player.maxHp,
      frenzy: 0,
      frenzyMax: this.frenzyMax,
    });
  }

  _resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    this.renderer.setSize(w, h, false);
    this.renderer.setPixelRatio(
      Math.min(window.devicePixelRatio || 1, this.isTouch ? 1.5 : 2)
    );
    const aspect = w / h;
    this.camera.aspect = aspect;
    this.camera.fov = aspect < 0.8 ? 62 : 52;
    this.camera.updateProjectionMatrix();
    this.viewW = w;
    this.viewH = h;
  }

  startRun() {
    this.audio.init();
    this.audio.startAmbience();
    this.audio.startGame();
    this._resetWorld();
    this.state = STATE.PLAYING;
    this.menuTime = 0;
    this.stateTimer = 0;
    this.heartTimer = 0;
    this.ui.showScreen("none");
    this.ui.toast("SECTOR 01 // CLEAR THE MAZE", "cool", 1900);
    this._snapCameraBehind(true);
  }

  _snapCameraBehind(dropIn = false) {
    this._desired.copy(this.player.pos).add(this._cameraOffset());
    if (dropIn) this._desired.y += 8;
    this.camera.position.copy(this._desired);
    this._cameraLook.copy(this.player.pos).setY(0.7);
    this.camera.lookAt(this._cameraLook);
  }

  _cameraOffset() {
    const portrait = this.viewW / this.viewH < 0.8;
    return portrait
      ? this._tmp.set(0, 30, 23)
      : this._tmp.set(0, 25, 19.5);
  }

  goMenu() {
    this.audio.stopAmbience();
    if (this.audio.ctx && this.audio.ctx.state === "suspended") this.audio.ctx.resume();
    this._resetWorld();
    this.state = STATE.MENU;
    this.menuTime = 0;
    this.ui.showScreen("menu");
    this.camera.position.set(0, 26, 34);
    this._cameraLook.set(0, 0, 0);
    this.camera.lookAt(0, 0, 0);
  }

  pause() {
    if (this.state !== STATE.PLAYING) return;
    this.state = STATE.PAUSED;
    this.ui.showScreen("pause");
    if (this.audio.ctx) this.audio.ctx.suspend().catch(() => {});
  }

  resume() {
    if (this.state !== STATE.PAUSED) return;
    this.state = STATE.PLAYING;
    this.ui.showScreen("none");
    if (this.audio.ctx) this.audio.ctx.resume().catch(() => {});
    this.clock.getDelta();
  }

  togglePause() {
    if (this.state === STATE.PLAYING) this.pause();
    else if (this.state === STATE.PAUSED) this.resume();
  }

  handleEnter() {
    if (this.state === STATE.MENU || this.state === STATE.OVER) this.startRun();
    else if (this.state === STATE.PAUSED) this.resume();
  }

  toggleMute() {
    this.audio.init();
    const muted = this.audio.toggleMuted();
    this.ui.setMuted(muted);
    if (!muted && this.state !== STATE.MENU && this.state !== STATE.PAUSED) {
      this.audio.startAmbience();
    }
  }

  _loop() {
    requestAnimationFrame(this._loop);
    const dt = Math.min(0.05, this.clock.getDelta());
    if (this.state !== STATE.PAUSED) {
      this.time += dt;
      this._update(dt);
    }
    this.renderer.render(this.scene, this.camera);
  }

  _update(dt) {
    const t = this.time;
    this.fx.update(dt, this.camera, this.viewW, this.viewH);
    this.maze.update(dt, t);
    this._updateOrbs(dt, t);

    if (this.state === STATE.MENU) {
      this.menuTime += dt;
      const angle = this.menuTime * 0.09;
      this.camera.position.set(Math.sin(angle) * 32, 24, Math.cos(angle) * 32);
      this._cameraLook.set(0, 0.6, 0);
      this.camera.lookAt(this._cameraLook);
      this.player.update(dt, this._move.set(0, 0), this._aimFallback.set(0, 0, -1), this.maze, t);
      this.ghosts.update(dt, t, this._tmp.set(0, 0, 0), this.maze);
      return;
    }

    if (this.state === STATE.PLAYING) {
      this._updatePlaying(dt, t);
      return;
    }

    if (this.state === STATE.DYING) {
      this.stateTimer -= dt;
      this._updateCamera(dt, 0.5);
      this.ui.update(this._hudState());
      if (this.stateTimer <= 0) this._finishGameOver();
      return;
    }

    if (this.state === STATE.CLEARED) {
      this.stateTimer -= dt;
      this.player.update(
        dt,
        this._move.set(0, 0),
        this._aimFallback.copy(this.player.aim),
        this.maze,
        t
      );
      this._updateCamera(dt, 0.8);
      this.ui.update(this._hudState());
      if (this.stateTimer <= 0) this._nextLevel();
      return;
    }

    if (this.state === STATE.OVER) {
      this._updateCamera(dt, 0.25);
      this.ui.update(this._hudState());
    }
  }

  _hudState() {
    return {
      score: this.score,
      level: this.level,
      pellets: this.maze.pelletsLeft,
      hp: this.player.hp,
      maxHp: this.player.maxHp,
      frenzy: this.frenzy,
      frenzyMax: this.frenzyMax,
    };
  }

  _updatePlaying(dt, t) {
    const input = this.input;
    input.getMove(this._move);

    const stickAim = input.getStickAim(this._stickAim);
    if (stickAim) {
      this._aimDir.set(stickAim.x, 0, stickAim.y);
      if (this._aimDir.lengthSq() > 0.0001) this._aimDir.normalize();
      this._aimFallback.copy(this._aimDir);
    } else if (input.pointer.active) {
      const rect = this.canvas.getBoundingClientRect();
      this._ndc.x = ((input.pointer.x - rect.left) / rect.width) * 2 - 1;
      this._ndc.y = -((input.pointer.y - rect.top) / rect.height) * 2 + 1;
      this._raycaster.setFromCamera(this._ndc, this.camera);
      this._plane = this._plane || new THREE.Plane(new THREE.Vector3(0, 1, 0), -1.0);
      if (this._raycaster.ray.intersectPlane(this._plane, this._aimPoint)) {
        const dx = this._aimPoint.x - this.player.pos.x;
        const dz = this._aimPoint.z - this.player.pos.z;
        const len = Math.hypot(dx, dz);
        if (len > 1.4) {
          this._aimDir.set(dx / len, 0, dz / len);
          this._aimFallback.copy(this._aimDir);
        }
      }
    }

    this.player.update(dt, this._move, this._aimDir, this.maze, t);
    this.playerLight.position.copy(this.player.pos).setY(3.2);

    if (this.frenzy > 0) {
      this.frenzy -= dt;
      if (this.frenzy <= 0) this._endFrenzy();
    }

    if (input.firing()) {
      const shot = this.player.tryFire();
      if (shot) {
        this._spawnBullet(shot);
        this.fx.flash(shot.muzzle, this.player.frenzy ? 0x6ff6ff : 0xffd166, 1.15);
        this.fx.spawnSparks(shot.muzzle, shot.dir, 0xffe27a, 3);
        this.fx.addShake(0.045);
        this.audio.shoot(this.player.frenzy);
      }
    }

    this._updateBullets(dt);

    const got = this.maze.collectAt(this.player.pos, 0.92);
    if (got.pellets > 0) {
      this.score += got.pellets * 10;
      this.audio.chomp();
      this.fx.addShake(0.012);
    }
    if (got.power > 0) this._startFrenzy();

    this.ghosts.update(dt, t, this.player.pos, this.maze);

    // Ghost / player contact
    if (this.player.alive) {
      for (const g of this.ghosts.ghosts) {
        if (!g.active || g.spawnProtect > 0) continue;
        const dx = g.pos.x - this.player.pos.x;
        const dz = g.pos.z - this.player.pos.z;
        if (dx * dx + dz * dz > 2.35) continue;
        if (this.player.frenzy) {
          g.die();
          this._ghostKilled(g);
          this.audio.eatGhost(this.combo);
        } else if (this.player.invuln <= 0) {
          this._damagePlayer(g.pos);
          const away = this._tmp.copy(g.pos).sub(this.player.pos).setY(0);
          if (away.lengthSq() > 0.001) {
            away.normalize();
            g.pos.addScaledVector(away, 1.1);
            this.maze.resolveCircle(g.pos, 0.62);
          }
          break;
        }
      }
    }

    this._updateCamera(dt, 1);
    this.ui.update(this._hudState());

    const pointerActive = !this.isTouch && this.input.pointer.active;
    this.ui.crosshair(
      this.input.pointer.x,
      this.input.pointer.y,
      pointerActive,
      this.input.firing()
    );

    if (this.player.hp === 1 && this.player.alive) {
      this.heartTimer -= dt;
      if (this.heartTimer <= 0) {
        this.audio.heartbeat();
        this.heartTimer = 1.05;
      }
    } else {
      this.heartTimer = 0;
    }

    if (this.maze.pelletsLeft <= 0 && this.state === STATE.PLAYING) this._levelClear();
  }

  _updateCamera(dt, followStrength = 1) {
    const offset = this._cameraOffset();
    this._desired.copy(this.player.pos).add(offset);
    const k = 1 - Math.exp(-4.5 * dt * followStrength);
    this.camera.position.lerp(this._desired, k);

    this._look
      .copy(this.player.pos)
      .addScaledVector(this.player.aim, 1.1)
      .setY(0.7 + this.player.pos.y * 0);
    const lk = 1 - Math.exp(-7 * dt * followStrength);
    this._cameraLook.lerp(this._look, lk);
    this.camera.lookAt(this._cameraLook);
    this.camera.position.add(this.fx.shakeOffset);
    this.camera.rotation.z += this.fx.roll;
  }

  _spawnBullet(shot) {
    const b = this.bullets[this.bulletCursor];
    this.bulletCursor = (this.bulletCursor + 1) % BULLET_COUNT;
    b.active = true;
    b.life = 1.3;
    b.dir.copy(shot.dir);
    b.vel.copy(shot.dir).multiplyScalar(BULLET_SPEED);
    const spawn = this._tmp.copy(shot.pos);
    if (this.maze.isWallAtWorld(spawn.x, spawn.z)) {
      spawn.copy(this.player.pos).addScaledVector(shot.dir, 1.25);
      spawn.y = 1.03;
    }
    b.mesh.position.copy(spawn);
    b.mesh.rotation.set(0, Math.atan2(shot.dir.x, shot.dir.z), 0);
    b.mesh.visible = true;
  }

  _updateBullets(dt) {
    for (const b of this.bullets) {
      if (!b.active) continue;
      this._prev.copy(b.mesh.position);
      b.mesh.position.addScaledVector(b.vel, dt);
      b.life -= dt;
      if (b.life <= 0) {
        b.active = false;
        b.mesh.visible = false;
        continue;
      }

      let hitWall = false;
      const steps = 4;
      for (let i = 1; i <= steps; i++) {
        const t = i / steps;
        const x = this._prev.x + (b.mesh.position.x - this._prev.x) * t;
        const z = this._prev.z + (b.mesh.position.z - this._prev.z) * t;
        if (this.maze.isWallAtWorld(x, z)) {
          hitWall = true;
          b.mesh.position.set(x, this._prev.y, z);
          break;
        }
      }
      if (hitWall) {
        this.fx.impact(b.mesh.position, 0xffd166);
        this.audio.hit();
        b.active = false;
        b.mesh.visible = false;
        continue;
      }

      for (const g of this.ghosts.ghosts) {
        if (!g.active) continue;
        const d2 = segmentDist2(
          this._prev.x,
          this._prev.z,
          b.mesh.position.x,
          b.mesh.position.z,
          g.pos.x,
          g.pos.z
        );
        if (d2 < 0.98) {
          const killed = g.hit(this.player.frenzy ? 99 : 1, b.dir);
          this.fx.spawnSparks(
            this._tmp.set(g.pos.x, 1.1, g.pos.z),
            b.dir,
            g.baseColor,
            6
          );
          this.fx.flash(this._tmp, g.baseColor, 1.5);
          this.fx.addShake(0.09);
          if (killed) this._ghostKilled(g);
          else this.audio.hit();
          b.active = false;
          b.mesh.visible = false;
          break;
        }
      }
    }
  }

  _ghostKilled(g) {
    this.kills++;
    const inFrenzy = this.player.frenzy;
    let value;
    if (inFrenzy) {
      this.combo += 1;
      value = 200 * Math.pow(2, Math.min(4, this.combo - 1));
    } else {
      value = 150;
    }
    this.score += value;
    const wp = g.worldPos;
    this.fx.spawnBurst(wp, g.baseColor, 44, 10.5, { life: 0.85, up: 0.55, gravity: 11 });
    this.fx.spawnBurst(wp, 0xffffff, 12, 5.5, { life: 0.4, gravity: 5, up: 0.8 });
    this.fx.ring(g.pos, g.baseColor, 0.9, 6.2, 0.6, 0.95);
    this.fx.flash(wp, g.baseColor, 2.6);
    this.fx.addShake(0.4);
    this.fx.popup(wp, `+${value}`, inFrenzy ? "combo" : "");
    if (inFrenzy && this.combo >= 2) {
      this.ui.toast(`GHOST CHAIN \u00d7${this.combo}`, "", 900);
    }
    if (!inFrenzy) this.audio.ghostDie();
    this.ui.popHeart?.();
  }

  _damagePlayer(sourcePos) {
    if (!this.player.damage()) return;
    this.audio.hurt();
    if (this.audio.ctx) {
      const p = new THREE.Vector3(this.player.pos.x, 1.15, this.player.pos.z);
      this.fx.spawnBurst(p, 0xff3b5f, 34, 8.5, { life: 0.7 });
      this.fx.spawnBurst(p, 0xffd400, 18, 6, { life: 0.6 });
      this.fx.flash(p, 0xff3b5f, 3.2);
      this.fx.ring(this.player.pos, 0xff3b5f, 1, 8, 0.7, 0.9);
    }
    this.fx.addShake(0.85);
    this.ui.flashDamage();
    this.ui.popHeart();
    const away = this._tmp.copy(this.player.pos).sub(sourcePos).setY(0);
    if (away.lengthSq() > 0.001) {
      away.normalize();
      this.player.pos.addScaledVector(away, 1.4);
      this.player.vel.addScaledVector(away, 5);
      this.maze.resolveCircle(this.player.pos, this.player.radius);
    }
    if (!this.player.alive) this._playerDied();
    else this.ui.toast(`HULL BREACH // ${this.player.hp} LEFT`, "danger", 1100);
  }

  _playerDied() {
    this.state = STATE.DYING;
    this.stateTimer = 1.65;
    this.audio.stopAmbience();
    this.audio.gameOver();
    const p = new THREE.Vector3(this.player.pos.x, 1.15, this.player.pos.z);
    this.fx.spawnBurst(p, 0xffd400, 80, 14, { life: 1.2, up: 0.7, gravity: 8 });
    this.fx.spawnBurst(p, 0xff3b5f, 40, 10, { life: 0.9 });
    this.fx.ring(this.player.pos, 0xffd400, 1, 20, 1.2, 1);
    this.fx.flash(p, 0xff6a5f, 5);
    this.fx.addShake(1);
    this.playerLight.intensity = 0;
  }

  _finishGameOver() {
    this.state = STATE.OVER;
    this.best = Math.max(this.best, this.score);
    this.ui.setBest(this.best);
    this.ui.showOver({
      score: this.score,
      best: this.best,
      level: this.level,
      kills: this.kills,
    });
    this.playerLight.intensity = 26;
  }

  _startFrenzy() {
    this.frenzyMax = Math.max(5.0, FRENZY_BASE - (this.level - 1) * 0.22);
    this.frenzy = this.frenzyMax;
    this.combo = 0;
    this.player.setFrenzy(true);
    this.ghosts.setFlee(true);
    this.audio.power();
    this.audio.setFrenzy(true);
    const p = new THREE.Vector3(this.player.pos.x, 1.1, this.player.pos.z);
    this.fx.ring(this.player.pos, 0x34ecff, 1, 15, 0.85, 1);
    this.fx.spawnBurst(p, 0x34ecff, 46, 9, { life: 0.9, up: 0.8 });
    this.fx.flash(p, 0x8df7ff, 4);
    this.fx.addShake(0.45);
    this.ui.toast("FRENZY // SHOOT ANYTHING THAT MOVES", "", 1700);
  }

  _endFrenzy() {
    this.frenzy = 0;
    this.combo = 0;
    this.player.setFrenzy(false);
    this.ghosts.setFlee(false);
    this.audio.setFrenzy(false);
    this.audio.powerEnd();
    this.ui.toast("FRENZY SPENT", "cool", 1100);
  }

  _levelClear() {
    this.state = STATE.CLEARED;
    this.stateTimer = 2.6;
    const bonus = 500 * this.level + this.player.hp * 100;
    this.score += bonus;
    this.frenzy = 0;
    this.combo = 0;
    this.player.setFrenzy(false);
    this.ghosts.setFlee(false);
    this.audio.setFrenzy(false);
    this.audio.levelClear(this.level);
    this.ui.showClear(this.level, bonus);
    const p = new THREE.Vector3(this.player.pos.x, 1.1, this.player.pos.z);
    this.fx.spawnBurst(p, 0xffd400, 50, 10, { life: 1, up: 0.8 });
    this.fx.ring(this.player.pos, 0xffd400, 2, 16, 1, 1);
    this.fx.addShake(0.5);
  }

  _nextLevel() {
    this.level += 1;
    this.maze.resetPellets(this.level);
    this.ghosts.reset(this.level);
    this.player.heal(1);
    this.player.invuln = Math.max(this.player.invuln, 1.2);
    this.frenzy = 0;
    this.combo = 0;
    this.state = STATE.PLAYING;
    this.ui.showScreen("none");
    this.ui.toast(`SECTOR ${pad(this.level)} // ${Math.min(8, 3 + this.level)} HOSTILES`, "cool", 1700);
    this.audio.startGame();
    this.audio.startAmbience();
    this._snapCameraBehind(true);
  }

  _spawnOrb(spec) {
    if (this.state !== STATE.PLAYING) return;
    const o = this.orbs[this.orbCursor];
    this.orbCursor = (this.orbCursor + 1) % ORB_COUNT;
    o.active = true;
    o.life = 5;
    o.dir.set(spec.dirX, 0, spec.dirZ).normalize();
    o.phase = Math.random() * 6.28;
    o.mesh.position.set(spec.x, spec.y ?? 1.15, spec.z);
    o.mesh.visible = true;
    this.fx.flash(o.mesh.position, 0xff3fbe, 1.2);
    this.audio.orbFire();
  }

  _updateOrbs(dt, t) {
    for (const o of this.orbs) {
      if (!o.active) continue;
      this._prev.copy(o.mesh.position);
      o.mesh.position.addScaledVector(o.dir, ORB_SPEED * dt);
      o.mesh.position.y = 1.12 + Math.sin(t * 9 + o.phase) * 0.06;
      o.life -= dt;
      if (o.life <= 0) {
        o.active = false;
        o.mesh.visible = false;
        continue;
      }
      let hitWall = false;
      const steps = 3;
      for (let i = 1; i <= steps; i++) {
        const k = i / steps;
        const x = this._prev.x + (o.mesh.position.x - this._prev.x) * k;
        const z = this._prev.z + (o.mesh.position.z - this._prev.z) * k;
        if (this.maze.isWallAtWorld(x, z)) {
          hitWall = true;
          o.mesh.position.set(x, o.mesh.position.y, z);
          break;
        }
      }
      if (hitWall) {
        this.fx.spawnBurst(o.mesh.position, 0xff3fbe, 14, 5, { life: 0.4 });
        this.fx.flash(o.mesh.position, 0xff3fbe, 1.6);
        this.audio.orbPop();
        o.active = false;
        o.mesh.visible = false;
        continue;
      }
      if (this.state === STATE.PLAYING && this.player.alive) {
        const dx = o.mesh.position.x - this.player.pos.x;
        const dz = o.mesh.position.z - this.player.pos.z;
        if (dx * dx + dz * dz < 1.0) {
          if (this.player.invuln <= 0) this._damagePlayer(o.mesh.position);
          this.fx.spawnBurst(o.mesh.position, 0xff3fbe, 18, 6, { life: 0.45 });
          this.audio.orbPop();
          o.active = false;
          o.mesh.visible = false;
        }
      }
    }
  }
}

