function segmentDist2(ax, az, bx, bz, cx, cz) {
  const abx = bx - ax;
  const abz = bz - az;
  const acx = cx - ax;
  const acz = cz - az;
  const len2 = abx * abx + abz * abz;
  let t = len2 > 0 ? (acx * abx + acz * abz) / len2 : 0;
  t = Math.max(0, Math.min(1, t));
  const px = ax + abx * t - cx;
  const pz = az + abz * t - cz;
  return px * px + pz * pz;
}

